INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (7, 'Biscoito Marilan Maizena 300g', 'biscoito marilan maizena 300g', 'Marilan', 1.0, '300g', 'biscoitos', '/images/produtos/113529_85d58817467d.png', 'Biscoito Marilan Maizena Pacote com 300g O Biscoito Marilan Maizena é conhecido por sua textura leve, delicada e sabor suave, sendo uma excelente opção para o café da manhã, lanche da tarde ou para diversas receitas. Produzido com ingredientes selecionados, proporciona uma experiência agradável em cada mordida. A embalagem de 300g é ideal para compartilhar com toda a família. Dicas de Uso: Perfeito para acompanhar café, leite, chá ou chocolate quente. Ideal para receitas de pavês, tortas e outras sobremesas. Ótima opção para lanches leves durante o dia. Conserve em local seco e mantenha a embalagem fechada após aberta. O Biscoito Marilan Maizena oferece tradição, qualidade e muito sabor, sendo uma escolha prática e versátil para toda a família.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
