INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (10, 'Açúcar Refinado Bulnez 1kg', 'açúcar refinado bulnez 1kg', 'Bulnez', 1.0, '1kg', 'mercearia', '/images/produtos/171471_50f7f83569e0.png', 'Açúcar Refinado Bulnez Pacote com 1kg O Açúcar Refinado Bulnez, em pacote com 1kg, possui textura fina e excelente pureza, sendo ideal para adoçar bebidas e preparar receitas que exigem um açúcar de rápida dissolução. Versátil e prático, é uma excelente escolha para o uso diário em cozinhas residenciais e comerciais. Dicas de Uso: Ideal para adoçar cafés, chás, sucos e outras bebidas. Perfeito para bolos, tortas, doces, cremes e sobremesas. Pode ser utilizado no preparo de caldas, mousses e recheios. Armazene em local seco e fresco, mantendo a embalagem bem fechada. O Açúcar Refinado Bulnez oferece praticidade, qualidade e excelente rendimento para o preparo de diversas receitas. Sua embalagem de 1kg é ideal para o consumo diário, proporcionando resultados consistentes e saborosos.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
