INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (161, 'Água Mineral Fonte da Lomba com Gás 510ml', 'água mineral fonte da lomba com gás 510ml', 'FONTE DA LOMBA', 1.0, '510ml', 'bebidas', '/images/produtos/9559028_7b22b54dd339.png', 'Descubra a refrescância efervescente que vem direto das fontes puras do sul do país. Essa água mineral gaseificada traz uma leveza incomparável, perfeita para acompanhar refeições leves ou momentos de hidratação intensa. Com bolhas finas que dançam na língua, ela oferece um equilíbrio natural de minerais essenciais para o bem-estar diário. Ideal para quem busca vitalidade sem excessos, sua composição mineralizada favorece a digestão e revitaliza o organismo de forma sutil. Orgulho do Rio Grande do Sul, ela representa a essência da natureza gaúcha em cada gole, convidando a uma experiência sensorial única e revigorante. Eleve seus dias com essa opção que une tradição e pureza, tornando cada instante mais vibrante e saudável.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (161, 7, 1.49, CURRENT_TIMESTAMP, 'rissul', 'Água Mineral Fonte da Lomba com Gás 510ml', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (162, 'Água Mineral Fonte da Lomba sem Gás 510ml', 'água mineral fonte da lomba sem gás 510ml', 'FONTE DA LOMBA', 1.0, '510ml', 'bebidas', '/images/produtos/9559479_e422a1ce0c0c.png', 'A pureza da fonte sulina se revela em cada gota dessa água mineral natural. Sem aditivos, ela hidrata profundamente, sendo a escolha perfeita para dias quentes ou rotinas agitadas. Sua suavidade inigualável proporciona um alívio imediato, mantendo o equilíbrio hídrico do corpo com elegância. Enriquecida por minerais naturais que brotam da terra generosa, essa bebida apoia a saúde geral, promovendo clareza mental e energia renovada. Direto do nosso Sul, ela carrega o vigor das paisagens verdejantes, oferecendo um toque de frescor autêntico em sua vida cotidiana. Transforme a hidratação em um ritual simples e prazeroso, com uma qualidade que reflete o cuidado com o que é essencial.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (162, 7, 1.29, CURRENT_TIMESTAMP, 'rissul', 'Água Mineral Fonte da Lomba sem Gás 510ml', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (163, 'Refrigerante Coca-Cola Pet 200ml', 'refrigerante coca-cola pet 200ml', 'COCA COLA', 1.0, '200ml', 'bebidas', '/images/produtos/9914452_efe61770f691.png', 'Clássico efervescente em porção compacta, pronto para acompanhar o dia a dia agitado. Seu sabor equilibrado traz alegria imediata, perfeito para pausas rápidas ou lanches informais. A carbonatação moderada cria bolhas que dançam, realçando o dulçor natural sem sobrecarregar. Versátil para misturas ou consumo direto, ela mantém a tradição viva em embalagens práticas. Celebre os pequenos momentos com essa bebida que une conveniência e deleite autêntico.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (163, 7, 1.69, CURRENT_TIMESTAMP, 'rissul', 'Refrigerante Coca-Cola Pet 200ml', TRUE);
