INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (164, 'Refrigerante Coca-Cola sem Açúcar Pet 200ml', 'refrigerante coca-cola sem açúcar pet 200ml', 'COCA COLA', 1.0, '200ml', 'bebidas', '/images/produtos/9914438_04d2719b2110.png', 'Sinta o clássico sabor que define momentos de alegria, agora sem o peso do açúcar. Essa versão sem açúcar mantém o equilíbrio perfeito de dulçor artificial que satisfaz o paladar sem comprometer a dieta. Não contém açúcar, tornando-a aliada ideal para quem monitora a ingestão calórica. Com um fizz vigoroso que desperta os sentidos, ela é versátil para misturas ou consumo puro, trazendo frescor em qualquer ocasião social ou solitária. Sua formulação cuidadosa preserva o aroma icônico, convidando a reviver memórias doces de forma leve e consciente. Opte por essa delícia que une tradição e modernidade, perfeita para um estilo de vida equilibrado e cheio de sabor.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
