INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (166, 'Refrigerante Pepsi Black sem Açúcar Pet 2L', 'refrigerante pepsi black sem açúcar pet 2l', 'PEPSI', 1.0, '2l', 'bebidas', '/images/produtos/9692084_e8f68e4b61ea.png', 'Experimente o intensidade escura e sem açúcar dessa bebida gaseificada. Seu perfil robusto, sem doçura excessiva, agrada a quem busca opções ousadas. Não contém açúcar, ideal para dietas restritivas ou momentos de indulgência controlada. O gás efervescente cria uma sensação revigorante, perfeita para energizar tardes longas ou noites animadas. Com sabor profundo que evolui no paladar, ela se destaca em combinações criativas ou sozinha, mantendo a essência clássica. Adote essa variante que redefine o prazer sem culpas, trazendo equilíbrio ao seu cotidiano efervescente.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (166, 7, 8.89, CURRENT_TIMESTAMP, 'rissul', 'Refrigerante Pepsi Black sem Açúcar Pet 2L', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (167, 'Água Mineral Fonte da Lomba com Gás 1,5L', 'água mineral fonte da lomba com gás 1,5l', 'FONTE DA LOMBA', 1.0, '1,5l', 'bebidas', '/images/produtos/9672567_a9439fb48017.png', 'A efervescência mineral dessa água captura a essência vibrante do sul brasileiro. Com gás natural, ela estimula o paladar de maneira delicada, ideal para paladares que apreciam texturas sutis. Sua pureza garante hidratação de alta qualidade em embalagem prática. Minerais equilibrados promovem benefícios digestivos e revitalizantes, tornando-a companheira inseparável de atividades diárias. Orgulho do Rio Grande do Sul, ela evoca a força da natureza local, proporcionando um gole que refresca corpo e mente simultaneamente. Incorpore essa fonte de vitalidade em sua rotina, descobrindo o prazer de uma hidratação autêntica e revigorante.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
