INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (169, 'Água Mineral Fonte da Lomba sem Gás 5L', 'água mineral fonte da lomba sem gás 5l', 'FONTE DA LOMBA', 1.0, '5l', 'bebidas', '/images/produtos/9367135_d8f60d311ed4.png', 'Garanta o estoque de saúde da sua casa com esta fonte de vida vinda diretamente do nosso Sul! Esta embalagem familiar de cinco litros é a base ideal para a hidratação diária de adultos e crianças, garantindo que todos aproveitem uma água leve, equilibrada e totalmente pura, extraída com todo o cuidado das nossas fontes gaúchas.\n\nPor ser rica em nutrientes minerais naturais e possuir um pH equilibrado, esta opção auxilia no bom funcionamento do organismo e na vitalidade geral, sendo indispensável para quem preza por um estilo de vida saudável e econômico. É o orgulho do Rio Grande do Sul entregando pureza e bem-estar em um formato prático para o consumo de toda a família ao longo da semana.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (169, 7, 6.59, CURRENT_TIMESTAMP, 'rissul', 'Água Mineral Fonte da Lomba sem Gás 5L', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (170, 'Refrigerante Coca-Cola sem Açúcar Pet 2L', 'refrigerante coca-cola sem açúcar pet 2l', 'COCA COLA', 1.0, '2l', 'bebidas', '/images/produtos/9047556_aac13105ee02.png', 'O ícone das bebidas efervescentes agora em versão sem açúcar, preservando o fizz inconfundível. Sem comprometer o sabor autêntico, ela oferece satisfação imediata para paladares exigentes. Não contém açúcar, facilitando escolhas conscientes em qualquer dieta. Em embalagem familiar, é perfeita para compartilhar em reuniões ou armazenar com facilidade. Sua carbonatação viva desperta os sentidos, tornando cada gole uma celebração de frescor e tradição consolidada. Integre essa opção leve à sua vida, desfrutando de momentos doces sem excessos calóricos.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
