INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (171, 'Cenoura', 'cenoura', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/20848_b25562af09bf.png', 'A Cenoura é o legume multitarefa que não pode faltar na sua geladeira. Crocante quando crua e aveludada quando cozida, ela agrada de crianças a adultos, sendo um dos alimentos mais completos para o dia a dia. Seja no bolo de cenoura do café da tarde ou no suco matinal, ela garante cor, doçura natural e uma dose extra de saúde para toda a família. Informações Nutricionais: Riquíssima em Betacaroteno (Pró-vitamina A). Benefícios para Saúde: Essencial para a saúde da visão, pele e cabelos. Sugestão de Preparo: Palitos de cenoura com homus ou cozida com mel e gengibre. Modo de Preparo: Pode ser consumida com casca (se bem lavada) ou descascada, ralada, em cubos ou rodelas. Sugestões de Armazenamento: Geladeira, dentro de um saco plástico perfurado, por até 2 semanas.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (171, 7, 6.79, CURRENT_TIMESTAMP, 'rissul', 'Cenoura', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (172, 'Batata Branca', 'batata branca', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/20251_bcbaa9ccc423.png', 'A Batata Branca é o ingrediente mais versátil da despensa, com uma textura que se adapta a infinitas possibilidades culinárias. Seja em um purê sedoso ou em um assado rústico, ela absorve os sabores dos temperos e garante saciedade com leveza. Um clássico que agrada a todos, essencial para compor refeições equilibradas e nutritivas para toda a família brasileira. Informações Nutricionais: Rica em potássio e vitaminas do complexo B. Benefícios para Saúde: Auxilia no bom funcionamento do sistema nervoso e fornece energia. Sugestão de Preparo: Purês, maioneses de legumes ou assada com alecrim. Modo de Preparo: Cozinhe em água com sal até ficar macia ou asse em forno médio. Sugestões de Armazenamento: Local fresco, seco e escuro para evitar a brotação.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
