INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (173, 'Cebola Nacional', 'cebola nacional', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/8389_b5b69cd5851e.png', 'A Cebola Nacional é o clássico indispensável na cozinha brasileira. Com seu sabor característico e aroma marcante, ela é a alma de quase todos os pratos, proporcionando aquela base de sabor que todos amamos. Valorize a produção nacional e leve para casa um produto fresco, versátil e essencial para dar personalidade a qualquer receita, das mais simples às mais complexas. Informações Nutricionais: Fonte de potássio e cálcio. Benefícios para Saúde: Auxilia na saúde do coração e possui propriedades expectorantes. Sugestão de Preparo: Cebola empanada frita ou como base para qualquer refogado. Modo de Preparo: Pique finamente para temperos ou em rodelas para frituras e assados. Sugestões de Armazenamento: Guardar em local arejado, seco e escuro.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (173, 7, 8.98, CURRENT_TIMESTAMP, 'rissul', 'Cebola Nacional', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (174, 'Ovos Brancos com 20un', 'ovos brancos com 20un', 'UNIDASUL', 1.0, '20un', 'mercearia', '/images/produtos/2203867_cab650597cbe.png', 'Praticidade e nutrição que não podem faltar na sua rotina. Seja no café da manhã proteico, naquele bolo fofinho ou no omelete rápido da noite, eles são seus melhores aliados. Sempre fresquinhos e prontos para salvar qualquer refeição com muita versatilidade. Saúde e sabor garantidos para toda a família!') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (174, 7, 12.98, CURRENT_TIMESTAMP, 'rissul', 'Ovos Brancos com 20un', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (175, 'Tomate Longa Vida', 'tomate longa vida', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/64880_f086b1735325.png', 'O Tomate Longa Vida une a praticidade da durabilidade com o frescor necessário para o dia a dia. Com casca firme e boa resistência, ele é o companheiro ideal para as compras da semana, mantendo-se bonito e saboroso por mais tempo. Versátil e confiável, ele atende a todas as necessidades da cozinha, desde o preparo de refogados até a salada rápida do almoço. Informações Nutricionais: Fonte de minerais e vitaminas essenciais. Benefícios para Saúde: Auxilia na hidratação e proteção celular. Sugestão de Preparo: Cubos para vinagretes ou base para refogados de legumes. Modo de Preparo: Lave bem e utilize conforme o grau de maturação desejado. Sugestões de Armazenamento: Local arejado e seco; dura mais que as variedades tradicionais.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (175, 7, 14.98, CURRENT_TIMESTAMP, 'rissul', 'Tomate Longa Vida', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (176, 'Batata Inglesa Rosa', 'batata inglesa rosa', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/62817_3d15a6965ef8.png', 'A Batata Inglesa Rosa destaca-se pela sua casca fina e polpa que mantém a firmeza após o cozimento, sendo a escolha preferida para saladas e pratos que exigem apresentação impecável. Seu sabor delicado eleva o nível dos acompanhamentos do dia a dia. Traga um toque de sofisticação e cor para o seu prato com esta variedade que combina textura perfeita e alto valor nutricional. Informações Nutricionais: Rica em vitamina C e antioxidantes na casca. Benefícios para Saúde: Auxilia na saúde da pele e no fortalecimento da imunidade. Sugestão de Preparo: Salada de batata com ervas ou assada inteira com casca. Modo de Preparo: Cozinhe com casca para preservar os nutrientes e a cor vibrante. Sugestões de Armazenamento: Geladeira ou local muito fresco para manter a firmeza da casca.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (176, 7, 8.49, CURRENT_TIMESTAMP, 'rissul', 'Batata Inglesa Rosa', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (177, 'Laranja-de-umbigo', 'laranja-de-umbigo', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/36115_4205a0c52ef1.png', 'Informações Nutricionais: Por 100g: Calorias: 47 kcal, Carboidratos: 11,8g, Proteínas: 0,9g, Gorduras: 0,1g, Fibra: 2,4g, Vitamina C: 53mg. Benefícios para Saúde: A laranja de umbigo é sem sementes e rica em potássio, ajudando na regulação da pressão arterial e na função muscular. Sugestão de Preparo: Use em saladas de frutas ou como lanche rápido. Modo de Preparo: Descasque removendo a casca branca e separe os gomos com cuidado. Sugestões de Armazenamento: Guarde em bandeja na geladeira por até 10 dias, evitando empilhamento.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (177, 7, 4.79, CURRENT_TIMESTAMP, 'rissul', 'Laranja-de-umbigo', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (178, 'Tomate Italiano', 'tomate italiano', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/28899_5fe3b786d70d.png', 'O Tomate Italiano é o preferido dos amantes da culinária por sua polpa carnuda, poucas sementes e sabor adocicado. É a base perfeita para o legítimo molho de tomate caseiro, entregando cor e textura incomparáveis. Transforme sua cozinha em uma verdadeira cantina italiana com este tomate selecionado que garante resultados profissionais em suas receitas. Informações Nutricionais: Rico em licopeno e fibras. Benefícios para Saúde: Melhora a saúde cardiovascular e auxilia na digestão. Sugestão de Preparo: Molho pomodoro clássico ou tomate seco caseiro. Modo de Preparo: Retire a pele e as sementes para molhos mais aveludados e sofisticados. Sugestões de Armazenamento: Geladeira apenas se estiverem muito maduros; caso contrário, local fresco.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (178, 7, 15.98, CURRENT_TIMESTAMP, 'rissul', 'Tomate Italiano', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (179, 'Maçã Fuji', 'maçã fuji', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/26611_4484965cba4f.png', 'Informações Nutricionais: Por 100g: Calorias: 52 kcal, Carboidratos: 13,8g, Proteínas: 0,3g, Gorduras: 0,2g, Fibra: 2,4g, Vitamina C: 4,6mg. Benefícios para Saúde: A maçã fuji tem alto teor de fibras solúveis, ajudando no controle do açúcar no sangue e na saúde digestiva. Sugestão de Preparo: Ideal para saladas ou consumida fresca. Modo de Preparo: Remova o caroço e fatie para adicionar a refeições. Sugestões de Armazenamento: Armazene em saco perfurado na geladeira por 2-3 semanas.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
