INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (180, 'Limão Taiti', 'limão taiti', 'UNIDASUL', 1.0, '1 un', 'mercearia', '/images/produtos/21463_669eb43166f4.png', 'Informações Nutricionais: Por 100g: Calorias: 29 kcal, Carboidratos: 9,3g, Proteínas: 1,1g, Gorduras: 0,3g, Fibra: 2,8g, Vitamina C: 53mg. Benefícios para Saúde: Sem sementes, o limão taiti auxilia na alcalinização do corpo e melhora a absorção de nutrientes. Bom para a saúde bucal. Sugestão de Preparo: Use em ceviches ou limonadas refrescantes. Modo de Preparo: Corte em quartos e esprema diretamente sobre alimentos. Sugestões de Armazenamento: Mantenha em temperatura ambiente por 4 dias ou refrigere por mais tempo.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
