INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (331, 'Creme de Leite CCGL Caixa 200g', 'creme de leite ccgl caixa 200g', 'Ccgl', 1.0, '200g', 'leites', '/images/produtos/1097672_090da0b9c50a.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Creme de Leite, da marca CCGL, em embalagem com 200 gramas. Sua textura cremosa e seu sabor suave compõem diversas receitas doces e salgadas, podendo ser adicionado a quiches, tortas, molhos, cremes, assim como a ganaches, mousses, pudins e bebidas quentes. Sua porção com 15 gramas (1 e 1/2 colher de sopa) possui, aproximadamente, valor energético de 29 kcal, 0,9 grama de carboidratos, 0,6 grama de proteínas e 8 miligramas de sódio. ALÉRGICOS: Contém lactose, leite e derivados de leite.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
