INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (332, 'Molho de Tomate Tradicional Heinz 240g', 'molho de tomate tradicional heinz 240g', 'Heinz', 1.0, '240g', 'mercearia', '/images/produtos/1124980_95d950f10755.jpg', 'Molho de Tomate Tradicional, da marca Heinz, em embalagem com 240 gramas. Ele se destaca pelo sabor encorpado e pela presença de pedaços selecionados de tomate, que conferem uma textura mais rústica e caseira às preparações culinárias. A formulação é cuidadosamente elaborada para oferecer uma experiência gastronômica equilibrada, sendo um ingrediente versátil para realçar desde massas clássicas, pizzas, risotos até pratos mais elaborados que exigem um toque especial. Um dos grandes diferenciais desta opção é a composição livre de gorduras totais, atendendo a consumidores que priorizam uma alimentação equilibrada sem sacrificar o prazer de comer bem. A escolha de tomates maduros e o processamento atento garantem uma cor vibrante e um aroma que remete aos preparos caseiros, preservando as características naturais do fruto. A consistência do molho permite que ele fixe muito bem aos alimentos, tornando-o ideal para o preparo de carnes, ensopados ou como base para lasanhas. Por ser um produto prático , ele se torna um fiel aliado na rotina de quem precisa de agilidade , mas não abre mão de um resultado final que remete ao sabor de comida feita em casa. Com esse molho, é possível trazer o gosto autêntico do tomate para receitas de forma prática e deliciosa . Sua porção de 60 gramas (3 colheres de sopa) contém 24 kcal, 5,7 gramas de carboidratos, 0,4 grama de proteínas e 217 miligramas de sódio. Para a conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta. INGREDIENTES: Tomate, açúcar invertido, amido modificado, sal, cebola, salsa, alho, manjericão, sálvia, orégano, tomilho, extrato de levedura, aroma natural, acidulante ácido cítrico. ALÉRGICOS: Pode conter soja. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Pré-Pronto Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
