INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (333, 'Óleo de Soja Coamo 900ml', 'óleo de soja coamo 900ml', 'Coamo', 1.0, '900ml', 'oleos', '/images/produtos/1097696_f5bea6c0faee.jpg', 'Óleo de Soja, da marca Coamo, em garrafa com 900 mililitros. Este óleo de soja refinado é um ingrediente essencial para a culinária do dia a dia, oferecendo versatilidade e qualidade. Proveniente de grãos selecionados, passa por um processo de refino que garante a pureza e a neutralidade do seu sabor, permitindo que os aromas dos alimentos se destaquem. O óleo de soja é reconhecido por sua versatilidade culinária , sendo um excelente substituto para outras gorduras em frituras, refogados, molhos e marinadas. Sua capacidade de suportar altas temperaturas o torna uma escolha confiável para métodos de cozimento que exigem calor intenso , sem comprometer a integridade nutricional ou o sabor dos pratos. Além disso, sua leveza contribui para que as preparações fiquem menos pesadas, e o processo de refino cuidadoso assegura a remoção de impurezas, resultando em um óleo límpido e de coloração dourada suave. Este óleo é uma fonte de ácidos graxos insaturados , importantes para uma dieta equilibrada quando consumidos com moderação. Sua aplicação se estende desde o preparo de bolos e tortas, onde contribui para a maciez, até o cozimento de legumes e carnes, garantindo uma textura crocante e saborosa. A escolha por este produto é uma decisão inteligente para quem busca um ingrediente versátil e de qualidade superior para o seu lar. Ele se integra perfeitamente a qualquer rotina de preparo de alimentos, facilitando a criação de pratos nutritivos e deliciosos para toda a família. Sua porção de 13 mililitros (1 colher de sopa) possui valor energético de 108 kcal e 12 gramas de gorduras totais. Para a conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta. ALÉRGICOS: Contém derivados de soja. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Refinado Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (333, 6, 7.69, CURRENT_TIMESTAMP, 'zaffari', 'Óleo de Soja Coamo 900ml', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (334, 'Creme de Leite Parmalat Caixa 200g', 'creme de leite parmalat caixa 200g', 'Parmalat', 1.0, '200g', 'leites', '/images/produtos/1089703_4edbe38736df.jpg', 'Creme de Leite, da marca Parmalat, em embalagem com 200 gramas. Apresentando 17% de gordura, é um ingrediente versátil e de alta qualidade, ideal para enriquecer as receitas culinárias. Sua fórmula garante uma textura aveludada e um sabor suave, que complementa tanto pratos doces quanto salgados. A embalagem é pensada para o uso doméstico, evitando desperdícios e mantendo o frescor do produto. A homogeneização do creme de leite assegura uma consistência uniforme , facilitando seu uso em diversas preparações. Ele pode ser batido para obter chantilly, incorporado em molhos para conferir cremosidade ou utilizado como base para mousses e sobremesas. A presença do selo "Alto em Gordura Saturada" é uma informação nutricional importante, que permite ao consumidor fazer escolhas conscientes. Este creme de leite é um excelente ingrediente para confeitaria , capaz de transformar bolos, tortas e outras delícias em verdadeiras obras de arte gastronômicas. Além disso, é um ótimo aliado para quem deseja adicionar um toque especial a pratos do dia a dia, como um purê de batatas mais cremoso ou um café mais saboroso. Também é um ingrediente útil na etapa de finalizações de molhos, gratinados e sopas, conferindo uma riqueza de sabor vantajosa. INGREDIENTES: Creme de leite, leite em pó desnatado, carragena, carboximetilcelulose sódica, celulose microcristalina, goma xantana, goma guar, citrato de sódio, alginato de sódio e fosfato dissódico. ALÉRGICOS: Contém lactose, leite e derivados. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Lactose Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (334, 6, 2.98, CURRENT_TIMESTAMP, 'zaffari', 'Creme de Leite Parmalat Caixa 200g', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (335, 'Leite Condensado Semidesnatado Piracanjuba 395g', 'leite condensado semidesnatado piracanjuba 395g', 'Piracanjuba', 1.0, '395g', 'leites', '/images/produtos/1043726_a37573c5d17e.jpg', 'Leite Condensado Semidesnatado, da marca Piracanjuba, em embalagem com 395 gramas. Elaborado a partir de leite semidesnatado , é uma opção que une sabor adocicado na medida certa com leveza e suavidade ao paladar. Sua textura é cremosa, densa e uniforme, garantindo excelente consistência às receitas , sem comprometer o sabor característico. Por ser semidesnatado, apresenta menor teor de gordura em comparação às versões tradicionais, mantendo a cremosidade e o perfil sensorial marcante. Seu sabor é equilibrado e levemente adocicado, ideal para preparações doces variadas. É extremamente versátil na cozinha, podendo ser utilizado no preparo de brigadeiros, pudins, mousses, tortas, pavês e coberturas, além de combinar bem com frutas frescas, panquecas, bolos, biscoitos, sorvetes e sobremesas geladas. Também pode ser utilizado no acompanhamento de bebidas como café, cappuccino, chocolate quente e até em preparações gourmet com drinques ou espumantes suaves. Seja no dia a dia ou em ocasiões especiais, contribui com sabor, textura e qualidade a diferentes tipos de preparo. Em sua porção de 20 gramas (1 e 1/2 colher de sopa), contém valor energético de 61 kcal, 1,6 grama de proteínas, 25 miligramas de sódio e 60 miligramas de cálcio . Para conservação do produto, recomenda-se mantê-lo em local seco e fresco, longe da incidência de luz solar direta. INGREDIENTES: Leite semidesnatado, açúcar, leite em pó desnatado e lactose. ALÉRGICOS: Contém lactose, leite e derivados. Não contém glúten. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Sem Glúten Contém Lactose Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
