INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (337, 'Leite Condensado Semidesnatado Moça Nestlé Caixa 395g', 'leite condensado semidesnatado moça nestlé caixa 395g', 'Moça', 1.0, '395g', 'leites', '/images/produtos/1025776_26a9d30d7e81.jpg', 'Leite Condensado Semidesnatado Moça, da marca Nestlé, em caixa com 395 gramas. Feito com ingredientes selecionados, ele tem uma textura cremosa e aveludada que facilita muito na hora de preparar receitas, misturando com facilidade e garantindo um resultado mais uniforme e bonito. A versão semidesnatada traz uma opção mais leve, com menos gordura, sem perder o sabor clássico e cremosidade . A embalagem de 395 gramas é prática, fácil de guardar e perfeita para o dia a dia. Ajuda a usar na quantidade certa, evitando desperdício e deixando tudo mais simples na rotina. É ideal para quem gosta de preparar um doce sem complicação, seja uma receita rápida ou algo mais caprichado. Na prática, é aquele ingrediente coringa que ajuda em várias situações na cozinha. Pode ser utilizado no preparo de brigadeiro com chocolate meio amargo, beijinho com coco fresco ou um pudim clássico com calda caramelizada. Também se destaca em mousses de maracujá ou limão. Em bolos, contribui para massas mais úmidas e recheios encorpados, como um bolo de cenoura com cobertura cremosa ou um bolo gelado de coco. Outra ideia é incorporá-lo em cafés especiais, vitaminas com frutas ou até em sobremesas geladas, como um creme para pavê com biscoitos e camadas de frutas. INGREDIENTES: Leite integral, açúcar e lactose. ALÉRGICOS: Contém lactose e leite. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Lactose Semidesnatado Sem Glúten Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
