INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (338, 'Açúcar Refinado Caravelas 1kg', 'açúcar refinado caravelas 1kg', 'Caravelas', 1.0, '1kg', 'mercearia', '/images/produtos/1014575_0eeeb1558fb4.jpg', 'Açúcar Refinado, da marca Caravelas, em embalagem com 1 quilo. Este açúcar é conhecido pela sua textura fina e solubilidade rápida, tornando-se ideal para adoçar uma variedade de bebidas, como cafés, chás e sucos, proporcionando um sabor doce e equilibrado. Além de seu uso cotidiano, o açúcar refinado é um ingrediente fundamental em receitas de confeitaria, sendo indispensável para a preparação de bolos, doces e sobremesas diversas. É a base para criar receitas clássicas como glacês, merengues e pastas de açúcar, conferindo a textura e doçura necessárias para realçar os sabores. Com sua versatilidade, ele pode ser utilizado em marinadas, molhos e até mesmo em pratos salgados, trazendo um toque de doçura que realça os sabores. É ideal para quem busca praticidade, garantindo sempre um ingrediente de qualidade à mão para as criações culinárias. Sua porção de 5 gramas (1 colher de chá) possui valor energético de 20 kcal e 5 gramas de carboidratos. O produto deve ser mantido em recipiente com tampa, garantindo a qualidade do açúcar.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
