INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (339, 'Tomate Pelado Capellini 400g', 'tomate pelado capellini 400g', 'Capellini', 1.0, '400g', 'mercearia', '/images/produtos/1010758_c8e22571ff42.jpg', 'Tomate Pelado, da marca Capellini, em lata com 400 gramas. Imerso em suco do próprio tomate, é suculento e conta com sabor adocicado, característico de tomates argentinos. Pode ser utilizado em inúmeras receitas, em especial aquelas de origem italiana, como massas, pizzas e bruschettas, assim como risotos, paellas, pratos de frutos do mar, em saladas e antepastos. Compõe uma combinação harmoniosa com muçarela de búfala, manjericão fresco e azeite de oliva. Sua porção de 130 gramas (1/2 xícara) possui valor energético de 24 kcal, 4,6 gramas de carboidratos, 0,9 grama de proteínas, 0,7 grama de fibra alimentar e 9 miligramas de sódio.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
