INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (340, 'Arroz Branco Blue Ville 1kg', 'arroz branco blue ville 1kg', 'Blue Ville', 1.0, '1kg', 'graos', '/images/produtos/1010643_783af7c9c932.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Arroz Branco, da marca Blue Ville, em embalagem com 1 quilo. Arroz do Tipo 1, é caracterizado por seus grãos finos e alongados, que são polidos. Quando cozido, apresenta grãos soltos, macios e com uma textura levemente firme, mantendo o sabor suave e característico do arroz branco. É ideal para compor refeições do dia a dia, acompanhando desde pratos simples até receitas mais elaboradas. Versátil e delicado, pode ser combinado a diversos acompanhamentos, como carnes, peixes, vegetais, feijões e saladas, além de ser uma excelente base para pratos como risotos e arroz de forno. Sua porção de 50 gramas (1/4 de xícara) possui valor energético de 172 kcal, 40 gramas de carboidratos, 3,2 gramas de proteínas, 0,6 grama de fibra alimentar e 5,1 miligramas de sódio. Para conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz direta. INGREDIENTES: Arroz polido. ALÉRGICOS: Pode conter soja.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
