INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (341, 'Água Mineral com Gás Tutti Giorni Blu 500ml', 'água mineral com gás tutti giorni blu 500ml', 'Tutti Giorni Blu', 1.0, '500ml', 'bebidas', '/images/produtos/1102609_1681c5a4be20.jpg', 'Água Mineral com Gás Blu, da marca Tutti Giorni, em embalagem de 500 mililitros. Trata-se de uma água mineral gaseificada indicada para quem aprecia bebidas leves, refrescantes e com presença equilibrada de gás, adequada tanto para o consumo diário quanto para ocasiões específicas. Sua gaseificação é artificial, resultando em bolhas finas e delicadas que proporcionam uma sensação suave ao paladar . Essa característica contribui para uma experiência de consumo agradável, sem excessiva efervescência, mantendo o frescor típico da água com gás. Por não conter calorias, é uma alternativa simples e funcional para hidratação , podendo ser incluída em diferentes rotinas alimentares. No consumo, apresenta sabor neutro e refrescante, sem interferir nas características dos alimentos ou bebidas que acompanha. A presença moderada de gás auxilia na limpeza do paladar , tornando o consumo mais agradável ao longo das refeições. Pode ser consumida pura ou utilizada como acompanhamento, mantendo estabilidade e frescor enquanto gelada. É uma opção versátil para acompanhar almoços, jantares e refeições leves, além de harmonizar bem com bebidas como café e vinho, ajudando a realçar sabores e equilibrar a experiência gustativa . Também se adapta a momentos informais do dia a dia, reuniões, eventos ou pausas durante o trabalho, oferecendo praticidade e discrição. Para conservação, recomenda-se manter o produto em local seco e fresco, ao abrigo da luz solar direta. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
