INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (342, 'Água Mineral sem Gás Tutti Giorni Blu 500ml', 'água mineral sem gás tutti giorni blu 500ml', 'Tutti Giorni Blu', 1.0, '500ml', 'bebidas', '/images/produtos/1102608_6024704a727b.jpg', 'Água Mineral Natural Sem Gás, da marca Tutti Giorni, em embalagem de 500 mililitros. Proveniente de fonte natural, é uma água indicada para o consumo diário , desenvolvida para oferecer hidratação simples, segura e consistente em diferentes momentos da rotina. Após a captação, a água passa por processos de controle, que asseguram sua pureza, frescor e padronização. Possui composição leve e equilibrada, com presença natural de minerais como potássio e magnésio , elementos associados ao funcionamento adequado do organismo e à reposição de eletrólitos perdidos ao longo do dia. Seu perfil neutro torna o consumo agradável, sem interferências no paladar. No consumo, apresenta sabor suave e refrescante , podendo ser ingerida em temperatura ambiente ou gelada, conforme a preferência. A leveza da água favorece a hidratação contínua, seja em períodos de maior atividade física, durante o trabalho ou em momentos de descanso. É uma opção funcional para manter o corpo hidratado de forma regular. Mostra-se versátil no dia a dia, sendo adequada para acompanhar refeições, lanches ou para o consumo entre horários. Também pode ser utilizada como base para preparo de sucos, bebidas e drinks, preservando o sabor dos ingredientes adicionados. O formato da garrafa de facilita o transporte em bolsas, mochilas ou lancheiras, permitindo o consumo fora de casa, no trabalho, na escola ou em deslocamentos. O consumo regular auxilia na manutenção do bem-estar físico e mental , contribuindo para a hidratação adequada ao longo do dia. Para conservação do produto, deve ser mantido sob refrigeração. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
