INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (343, 'Refrigerante Coca-Cola sem Açúcar 200ml', 'refrigerante coca-cola sem açúcar 200ml', 'Coca-Cola', 1.0, '200ml', 'bebidas', '/images/produtos/1061521_7e2b1ebdd1ee.jpg', 'Refrigerante sem Açúcar, da marca Coca-Cola, em embalagem com 200 mililitros. Esta bebida oferece a experiência inconfundível do sabor tradicional com uma formulação sem adição de açúcares. Perfeita para acompanhar refeições, celebrar momentos especiais ou simplesmente para refrescar o dia, a versão sem açúcar mantém o prazer que se espera de um Coca-Cola. Sua composição cuidadosamente elaborada garante um paladar equilibrado e uma sensação revigorante a cada gole. Ideal para ser servida bem gelada, esta bebida é uma excelente opção para diversas ocasiões. Seja em um churrasco com amigos, um almoço em família ou como um agrado pessoal durante a tarde, sua versatilidade a torna um item indispensável na despensa. A embalagem de 200 mililitros é prática, ideal para o consumo individual, por equivaler à quantidade de um copo. A ausência de açúcar na composição a torna uma escolha interessante para quem está atento à ingestão calórica ou para aqueles que preferem evitar o consumo de açúcares. A refrescância é imediata, ideal para os dias mais quentes. Sua capacidade de versatilidade permite que seja combinada com uma ampla gama de alimentos, desde salgados até doces, realçando os sabores. Além disso, a Coca-Cola sem Açúcar é uma ótima alternativa para quem busca uma bebida zero calorias . A experiência de consumo é completa, satisfazendo o desejo por uma bebida saborosa e efervescente. Para conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta, preferencialmente sob refrigeração para melhor experiência. INGREDIENTES: Água gaseificada, extrato de noz de cola, cafeína, corante caramelo IV, acidulante ácido fosfórico e aroma natural. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
