INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (344, 'Água Mineral sem Gás Água da Pedra 500ml', 'água mineral sem gás água da pedra 500ml', 'Água da Pedra', 1.0, '500ml', 'bebidas', '/images/produtos/1045492_d58dde0bcb60.jpg', 'Água Mineral sem Gás, da marca Água da Pedra, em garrafa com 500 mililitros. É uma opção versátil para quem busca qualidade e comodidade no dia a dia. Extraída de uma fonte natural , essa água é reconhecida por sua pureza e frescor, proporcionando uma hidratação eficiente e equilibrada. Sua composição natural, livre de aditivos químicos, garante um sabor leve e agradável, tornando-a uma escolha ideal para consumo diário . Além de ser uma excelente fonte de hidratação , é ideal para complementar diferentes momentos, seja durante a prática de exercícios físicos, no ambiente de trabalho ou em momentos de lazer. Sua embalagem compacta e ergonômica permite que seja facilmente transportada, seja na bolsa, mochila ou porta-copos do carro, garantindo a hidratação em qualquer ocasião. Versátil, pode ser apreciada gelada para dias mais quentes, ou em temperatura ambiente, adaptando-se às necessidades e preferências. Além disso, é uma ótima companheira para refeições, harmonizando-se tanto com pratos simples quanto com gastronomias mais elaboradas, realçando os sabores sem interferir no paladar. Com volume ideal para o consumo individual, atende às rotinas mais dinâmicas, oferecendo praticidade sem abrir mão da qualidade. É uma escolha funcional para manter a hidratação ao longo do dia, acompanhando diferentes atividades e estilos de vida. Para conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
