INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (345, 'Água Mineral com Gás Água da Pedra 500ml', 'água mineral com gás água da pedra 500ml', 'Água da Pedra', 1.0, '500ml', 'bebidas', '/images/produtos/1038070_9efdac1e0401.jpg', 'Água Mineral com Gás, da marca Água da Pedra, em garrafa com 500 mililitros. Gaseificada artificialmente, é uma opção refrescante, ideal para quem busca uma bebida leve. Proveniente das fontes naturais, é conhecida por sua pureza e seu sabor único, que resulta de sua mineralização equilibrada e rica em sais minerais. Ela oferece uma efervescência delicada e agradável, sendo perfeita para quem aprecia a leveza das águas gaseificadas. Seu sabor neutro e refrescante combina facilmente com uma variedade de alimentos e de drinks, como coquetéis, vinhos e pratos leves, além de ser uma excelente escolha para acompanhar refeições ou para se refrescar ao longo do dia. Sua embalagem de 500 mililitros torna-a prática para levar em bolsas, mochilas ou consumir individualmente, sendo ideal para momentos de descontração e jantares ou para uma opção de hidratação no dia a dia. Pode ser consumida gelada ou fora do gelo. Ela atende às rotinas mais dinâmicas, oferecendo praticidade sem abrir mão da hidratação . É uma escolha funcional para manter a hidratação ao longo do dia, acompanhando diferentes atividades e estilos de vida. Para conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta COMPOSIÇÃO: Cálcio: 26,48mg/l; Sódio: 22,84mg/l; Potássio: 1,04mg/l; Fluoreto: 0,16mg/l; Bicarbonato: 131,99mg/l; Silício: 35,59mg/l; Magnésio: 5,14mg/l; Cloreto: 7,59mg/l; Vanádio: 0,012mg/l. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
