INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (348, 'Água Mineral sem Gás Tutti Giorni Blu 5 Litros', 'água mineral sem gás tutti giorni blu 5 litros', 'Tutti Giorni Blu', 1.0, '5 l', 'bebidas', '/images/produtos/1102610_69de259a1749.jpg', 'Água Mineral sem Gás Blu, da marca exclusiva Tutti Giorni, em garrafa com 5 litros. A escolha da fonte de hidratação diária impacta diretamente no bem-estar e na disposição ao longo da rotina. Esta opção apresenta uma composição equilibrada, ideal para quem busca pureza e leveza em cada gole. Com um rigoroso controle de qualidade desde a captação até o envase, o produto garante a preservação das suas propriedades naturais, oferecendo uma experiência de consumo refrescante e segura para toda a família. A presença de sais minerais essenciais confere ao líquido um sabor suave e agradável ao paladar, tornando-o um excelente acompanhamento para as refeições ou um aliado durante a prática de atividades físicas. O compromisso com a saúde reflete-se na transparência e na pureza deste recurso natural, e a ausência de gás permite uma versatilidade maior no uso culinário, respeitando o sabor original dos ingredientes. Além disso, a qualidade da água é um fator determinante para o bom funcionamento do organismo, auxiliando no transporte de nutrientes e na regulação térmica corporal. Incluir este item à rotina significa priorizar a saúde com simplicidade, contando com uma fonte confiável que atende às necessidades básicas de hidratação com eficiência, frescor e um padrão de pureza que faz a diferença na qualidade de vida cotidiana. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
