INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (349, 'Refrigerante Fruki Guaraná Zero 200ml', 'refrigerante fruki guaraná zero 200ml', 'Fruki', 1.0, '200ml', 'bebidas', '/images/produtos/1087562_f56e7d53446f.jpg', 'Refrigerante de Guaraná Zero Açúcar, da marca Fruki, em garrafinha com 200 mililitros. É uma alternativa refrescante e saborosa para quem busca uma bebida sem açúcar , com a tradicional energia e gosto do guaraná. Seu sabor é leve e doce , com um toque suave de amargor, que traz uma sensação de frescor. A falta de açúcar não compromete o sabor, o que torna a bebida uma ótima opção para quem busca reduzir calorias sem abrir mão do prazer de beber algo saboroso. Seu aroma é agradável, com notas de guaraná e um toque cítrico , despertando os sentidos. A textura é leve e borbulhante, com a efervescência característica dos refrigerantes, proporcionando uma sensação de frescor ao paladar. É ideal para ser consumido em diversas ocasiões, como festas, churrascos ou dias quentes. Combina perfeitamente com pratos como pizzas, petiscos, carnes grelhadas e sobremesas leves, como gelados e pudins, tornando-se uma opção versátil para acompanhar refeições e momentos de lazer. Sua porção de 200 mililitros possui, aproximadamente, 9 miligramas de sódio. A bebida não contém quantidades significativas de valor energético, de carboidratos, de gorduras totais e de proteínas. Para a conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta. INGREDIENTES: Água gaseificada, extrato natural de guaraná, acidulante ácido cítrico, edulcorantes ciclamato de sódio, sacarina sódica, acessulfame de potássio e sucralose, conservador benzoato de sódio, corante caramelo IV, aromatizante sintético idêntico ao natural. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Zero Açúcar Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
