INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (350, 'Água Mineral sem Gás Água da Pedra 5 Litros', 'água mineral sem gás água da pedra 5 litros', 'Água da Pedra', 1.0, '5 l', 'bebidas', '/images/produtos/1045483_e61bcd9363a6.jpg', 'Água Mineral Sem Gás, da marca Água da Pedra, em embalagem com 5 litros. É um produto que se destaca pela sua origem natural e qualidade excepcional. Captada diretamente da fonte localizada na cidade de Lajeado, essa água é reconhecida por sua pureza incontestável e frescor inigualável, características que são preservadas graças a um rigoroso processo de envase. Seu sabor suave e agradável proporciona uma experiência refrescante, sendo perfeita para manter o corpo hidratado em qualquer momento do dia. A embalagem de 5 litros é especialmente prática para atender às necessidades de famílias, escritórios ou eventos sociais, como confraternizações, celebrações ou encontros informais, momentos em que a demanda por uma bebida de qualidade é maior. Sua versatilidade permite que seja apreciada gelada em momentos de calor intenso, ou em temperatura ambiente, mantendo sempre o seu sabor característico. Recomenda-se que a bebida seja mantida em local seco e fresco ou sob refrigeração.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
