INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (352, 'Filé de Peito de Frango Resfriado Nat Verde 600g', 'filé de peito de frango resfriado nat verde 600g', 'Nat', 1.0, '600g', 'carnes', '/images/produtos/1087107_9ab3ee041bf5.jpg', 'Filé de Peito de Frango Resfriado Verde, da marca Nat, em embalagem com 600 gramas. Parte da linha Verde, esse corte é reconhecido por seu sabor suave , textura macia e extrema versatilidade, permitindo o preparo de pratos variados, como grelhados, refogados, assados e até empanados. A ausência de antibióticos em sua composição é um diferencial importante, assegurando um produto mais puro e confiável para o consumo. A ração 100% vegetal utilizada na alimentação das aves contribui para a qualidade da carne, resultando em um filé macio e suculento . Já vem em filés, prontos para serem utilizados, otimizando o tempo na cozinha. Pode ser usado para preparar frango desfiado ou até mesmo uma opção prática para grelhar e ser servido durante o almoço. É ideal para quem valoriza um estilo de vida saudável sem abrir mão do sabor e da praticidade. É uma ótima base para refeições nutritivas e deliciosas, atendendo às necessidades de quem busca uma alimentação equilibrada sem abrir mão do prazer de comer bem. A carne resfriada, quando armazenada corretamente, oferece uma experiência culinária superior. Sua porção de 125 gramas (1/2 unidade) possui valor energético de 125 kcal, 26 gramas de proteínas, 2,3 gramas de gorduras totais e 56 miligramas de sódio. Para garantir sua qualidade e frescor, o produto deve ser mantido sob refrigeração, em temperatura entre 0°C e 4°C. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Carne de Aves Cortes Tradicionais Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
