INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (353, 'Filé de Peito de Frango Congelado Nat 1kg', 'filé de peito de frango congelado nat 1kg', 'Nat', 1.0, '1kg', 'carnes', '/images/produtos/1003624_f0b433bc99ed.jpg', 'Filé de Peito de Frango Congelado, da marca Nat, em embalagem com 1 quilo. Sendo uma opção versátil e saborosa para as refeições, é caracterizado por sua textura macia e delicada. Retirado da parte dianteira do frango, especificamente do peito, é livre de ossos e considerado uma carne magra, já que possui baixa quantidade de gorduras. O congelamento individual das peças traz ainda mais praticidade , permitindo utilizar apenas a quantidade necessária, evitando desperdícios e facilitando a organização na cozinha. Ao ser preparado, mantém sua suculência e absorve temperos com facilidade, valorizando aromas e sabores de ervas, especiarias e molhos. Na rotina culinária, esse filé se adapta a diferentes receitas e ocasiões. Pode ser grelhado até atingir uma superfície dourada e levemente crocante, sendo perfeito para acompanhar arroz soltinho e legumes salteados. Em preparações assadas , combina com batatas e ervas. Também pode ser desfiado para rechear tortas, panquecas e sanduíches ou ainda incorporado em molhos cremosos para massas. Em cubos , pode ser utilizado em refogados com vegetais, trazendo leveza e equilíbrio ao prato. Seu sabor neutro permite explorar combinações diversas, desde temperos mais simples, como alho e sal, até marinadas mais elaboradas com limão, ervas frescas e especiarias. Para conservar suas melhores características, recomenda-se mantê-lo sob refrigeração adequada, garantindo que sua qualidade e frescor sejam preservados até o momento do preparo. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Carne de Aves Carne Branca Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
