INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (356, 'Filé de Coxa e Sobrecoxa de Frango sem Pele Congelado IQF Nat Verde 1kg', 'filé de coxa e sobrecoxa de frango sem pele congelado iqf nat verde 1kg', 'Nat', 1.0, '1kg', 'carnes', '/images/produtos/1108429_a28fc8deb946.jpg', 'Filé de Coxa e Sobrecoxa de Frango sem Pele Congelado IQF Verde, da marca Nat, em embalagem com 1 quilo. O corte reúne a suculência característica da coxa com a textura macia da sobrecoxa, resultando em pedaços que ficam dourados por fora e tenros por dentro quando preparados corretamente. Pode ser preparado na frigideira, na churrasqueira, no forno ou na air fryer , explorando diferentes pontos de textura e intensidade. Por ser um corte sem osso e sem pele , também facilita o manuseio e permite que a carne seja incorporada a receitas do cotidiano. Na cozinha, o filé pode ganhar destaque em preparações simples, como uma refeição com arroz branco, feijão e legumes assados, ou receber um toque mais elaborado com ervas, alho e limão antes de ser levado ao forno. Outra possibilidade é preparar os filés grelhados e servi-los com molho de mostarda e mel, acompanhados de batatas rústicas e uma salada de folhas. Os filés podem ser grelhados com páprica, cominho e limão e servidos em tacos com alface, tomate, cebola-roxa e guacamole. Outra sugestão é preparar o frango em cubos com legumes salteados, como cenoura, brócolis e pimentões, finalizando com molho de soja e gergelim. Para um almoço mais elaborado, os pedaços podem ser assados com batatas, cebola, alho e alecrim, formando uma combinação aromática e cheia de textura. O filé também pode ser desfiado depois de cozido e utilizado como recheio de sanduíches, wraps, panquecas, tortas salgadas e crepes. Sua porção de 82 gramas possui valor energético de 125 kcal, 19 gramas de proteínas, 8,5 gramas de gorduras totais e 59 miligramas de sódio . .index-selos { display:flex; }.grupo { 