INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (357, 'Filé de Tilápia Congelado Fantasia Di Mare 800g', 'filé de tilápia congelado fantasia di mare 800g', 'Fantasia Di Mare', 1.0, '800g', 'carnes', '/images/produtos/1097372_5226e78460b0.jpg', 'Filé de Tilápia Congelado, da marca Fantasia Di Mare, em embalagem com 800 gramas. É uma escolha prática para quem busca qualidade e sabor no dia a dia. Produzido a partir de peixe selecionado, apresenta textura firme e sabor suave, características ideais para diferentes preparações culinárias. O sistema de congelamento individual "um a um" facilita o uso no cotidiano, permitindo retirar apenas a quantidade necessária, evitando desperdícios e mantendo o restante do produto bem conservado. Além disso, por ser um filé sem pele e praticamente sem espinhas, o preparo se torna mais simples e rápido, ideal para rotinas dinâmicas. A versatilidade deste peixe branco permite seu uso em diversas receitas. Pode ser preparado grelhado com ervas, assado com legumes, empanado para uma versão crocante ou cozido em molhos leves. Também é uma excelente opção para pratos como tilápia ao forno com batatas, filé ao molho de limão, moquecas, tacos de peixe, saladas proteicas ou até em bowls com arroz e vegetais. Sua capacidade de absorver temperos valoriza ainda mais o resultado final. Do ponto de vista nutricional, é uma excelente fonte de proteínas de alto valor biológico , contribuindo para a manutenção muscular e para uma rotina alimentar equilibrada. Por ser uma opção de proteína magra , é ideal para quem busca refeições leves. A origem nacional reforça o cuidado com o frescor. Além disso, o preparo e o descongelamento rápido tornam este filé uma solução eficiente para a rotina. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Pescados Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
