INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (359, 'Coxa com Sobrecoxa de Frango Congelada', 'coxa com sobrecoxa de frango congelada', 'Açougue', 1.0, '1 un', 'carnes', '/images/produtos/1005720_7f9d23518ba7.jpg', 'Coxa com Sobrecoxa de Frango Congelada, vendida por peso. Este corte é amplamente reconhecido pela versatilidade e suculência, sendo uma escolha recorrente para o preparo de refeições cotidianas ou ocasiões especiais. A peça mantém a integridade da pele, o que auxilia na preservação da umidade natural da carne durante o cozimento, resultando em um interior macio e um exterior que pode atingir o ponto ideal de crocância . Por ser um corte com maior teor de gordura intramuscular em comparação ao peito, apresenta um sabor mais acentuado. O processo de congelamento é realizado com rigor técnico para garantir a manutenção das propriedades nutricionais e a qualidade do item até o momento do uso. A praticidade é um dos pilares, facilitando o planejamento do cardápio semanal. Ao ser preparado, demonstra excelente absorção de temperos , permitindo que marinadas, ervas e demais especiarias se incorporem profundamente às fibras, elevando o resultado final de qualquer receita. Seja assado no forno , grelhado na brasa , cozido em ensopados , na churrasqueira , acompanhado de legumes assados ou servido com purê de batatas . Rica em proteína de alto valor biológico , a Coxa com Sobrecoxa de Frango contribui para uma alimentação equilibrada e refeições completas. Cortes de qualidade e porções padronizadas proporcionam praticidade, bom rendimento e um ótimo custo-benefício. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Carne de Aves Carne Branca Cortes Tradicionais Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
