INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (360, 'Sobrecoxa de Frango Congelada IQF Nat 1kg', 'sobrecoxa de frango congelada iqf nat 1kg', 'Nat', 1.0, '1kg', 'carnes', '/images/produtos/1002878_6b00a4d5603c.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Sobrecoxa de Frango Congelada, da marca Nat, em embalagem com 1 quilo. É uma escolha prática e saborosa para quem busca versatilidade na cozinha. Com peças congeladas individualmente, vem em pacote com sistema Abre & Fecha, que ajuda no armazenamento e conservação. Sua suculência e sua textura macia tornam-na ideal para diversos preparos, como assados, grelhados, cozidos ou fritos. O sabor característico do frango pode ser realçado quando combinado com temperos como alho, ervas finas e limão. A embalagem de 1 quilo oferece praticidade, atendendo desde refeições do dia a dia até ocasiões especiais. Além disso, é uma fonte rica em proteínas, contribuindo para uma alimentação equilibrada. Para harmonizar, vinhos brancos leves ou sucos cítricos complementam perfeitamente pratos com essas sobrecoxas. É uma opção que alia praticidade, sabor e nutrição. Em sua porção de 100 gramas, contém, aproximadamente, valor energético de 242 kcal, 16 gramas de proteínas, 19 gramas de gorduras totais e 82 miligramas de sódio. Para conservação do produto, deve ser mantido no congelador até a ocasião de preparo. Descrição do Produto .index-selos { display: flex; } .grupo1, .grupo2 { display: flex; max-width: 300px; } .selo { width: 100%; text-align:center; background-color: transparent; border: 1px solid transparent; padding: 15px 15px; } .selo img { width: 100px; } .selo p { font-weight: bold; font-size: 12px; text-transform: uppercase; } @media screen and (min-width: 320px) and (max-width:1023px) { .index-selos { flex-direction: column; } .grupo1 { width: 100%; } } Carne Branca Carne de Aves') ON CONFLICT (id) DO