INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (362, 'Pão Cacetinho Pão Francês Zaffari', 'pão cacetinho pão francês zaffari', 'Zaffari', 1.0, '1 un', 'mercearia', '/images/produtos/1001429_3e9dd1cbe748.jpg', 'Pão Cacetinho ou Pão Francês, da marca Zaffari, vendido por unidade ou por peso. Também conhecido como pão de sal, pão de trigo ou pão d’água, é um clássico presente na rotina, perfeito para quem valoriza praticidade e um sabor que agrada em qualquer momento do dia. Não contém lactose , sendo uma alternativa que atende a diferentes preferências de consumo. Seu formato tradicional e tamanho equilibrado fazem dele uma escolha certeira para lanches , cafés da manhã ou até refeições rápidas ao longo do dia, sempre com aquele toque caseiro . A principal característica está na sua casca crocante , levemente dourada, que contrasta com o miolo macio , criando uma experiência agradável a cada mordida. Esse equilíbrio de texturas torna o consumo ainda mais interessante, seja puro ou combinado com diversos acompanhamentos. No dia a dia, pode ser servido ainda quentinho com manteiga derretendo, criando um café da manhã simples e acolhedor. Também combina muito bem com geleias de frutas, requeijão, pastas diversas ou fatias de presunto e queijo, compondo lanches rápidos e saborosos. Em preparações mais elaboradas, pode ser utilizado como base para sanduíches prensados, recheados com frango desfiado, carne assada ou legumes grelhados. Na Loja Online Zaffari , você ainda pode escolher o pão conforme sua preferência de preparo: mais dourado , menos dourado ou, se for o caso, sem preferência , basta selecionar na aba "Escolha sua preferência" e garantir que ele chegue do jeitinho que você gosta. INGREDIENTES: Farinha de trigo enriquecida com ferro e ácido fólico, sal, óleo de soja e fermento biológico. ALÉRGICOS: Contém glúten, lactose e derivados de soja. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Glúten Sem Lactose Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
