INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (363, 'Pão Cacetinho Pão Francês Zaffari', 'pão cacetinho pão francês zaffari', 'Zaffari', 1.0, '1 un', 'mercearia', '/images/produtos/1077397_a948fa2ba1b6.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Pão Francês, da marca Zaffari, vendido por peso. É um clássico irresistível que une tradição, frescor e qualidade. Com casca dourada e crocante, seu interior é macio, leve e aerado, com um aroma inconfundível que remete ao café da manhã em família. Seu sabor é equilibrado, levemente amanteigado, ideal para ser apreciado puro, com manteiga derretendo ainda quente ou acompanhado de queijos, frios, geleias e pastas cremosas. Versátil, pode ser consumido em diversas ocasiões: no café da manhã, no lanche da tarde ou em um lanche a qualquer hora. É ideal para servir como base para sanduíches ou como acompanhamento de sopas, caldos e saladas. Vai muito bem com um café preto forte, suco natural, leite ou, até mesmo, taça de vinho em refeições mais elaboradas. Seja recheado ou servido com requeijão, o Pão Francês Zaffari traz acalento e sabor a qualquer momento do dia. Entre seus ingredientes estão farinha de trigo enriquecida com ferro e ácido fólico, sal, óleo de soja e fermento biológico. Sua porção de 40 gramas possui valor energético de 107 kcal, 3,1 gramas de proteínas, 22,5 gramas de carboidratos, 0,3 grama de gorduras totais e 219 miligramas de sódio. Para conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta. ALÉRGICOS: Contém glúten.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
