INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (365, 'Pão Cacetinho Integral Pão Francês Zaffari', 'pão cacetinho integral pão francês zaffari', 'Zaffari', 1.0, '1 un', 'mercearia', '/images/produtos/1098011_3d9f1a833965.jpg', 'Pão Cacetinho Francês Integral, da marca Zaffari, vendido em unidade ou por peso. Tem textura crocante por fora e interior macio , com adição de farinha integral , o item ganha sabor mais intenso e textura rústica. É uma opção perfeita para quem quer incluir mais fibras na dieta ou para quem está procurando uma alternativa ao tradicional pão francês. Sua textura também permite diferentes possibilidades à mesa: pode ser consumido puro, com manteiga derretendo sobre o miolo, ou transformado em sanduíches e preparos rápidos. No café da manhã, experimente servi-lo ainda morno com manteiga , requeijão cremoso ou cream cheese, acompanhando café coado, cappuccino ou chá. Para uma combinação agridoce, uma camada de geleia de frutas vermelhas, damasco ou figo cria um contraste interessante com o sabor mais intenso do pão. Nos lanches , o pão pode ganhar recheios como peito de peru, queijo, tomate e folhas frescas, formando um sanduíche simples e saboroso. Também fica ótimo com frango desfiado, requeijão e ervas, ou com atum, cenoura ralada e folhas verdes. Sua porção de 40 gramas (1 unidade) contém valor energético de 101 kcal, 19 gramas de carboidratos, 3,7 gramas de proteínas, 2,7 gramas de fibra alimentar e 202 miligramas de sódio . Recomenda-se armazenar o alimento em local seco e fresco, longe da incidência de luz solar. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Glúten Integral .tabela-dados { width:100%; max-width:756px; border-collapse:collapse; margin:0 auto; color:#242424; }.tabela-dados td { padding:6px; height:51px; width:50%; vertical-align:middle; }.tabela-dados tr:nth-child(even) td { background-color:#ffffff; }.tabela-dados tr:nth-child(odd) td { background-color:#f5f7f5;}.tabela-dados td:first-child { text-align:right; font-weight:bold; }.cabecalho-tabela-nutricional { width:100%; max-width:756px; margin:6px auto 6px; color:#173a35; }.titulo-tabela-nutricional { margin:0; text-align:center; font-size:18px; font-weight:700; text-transform:uppercase; }.porcao-tabela-nutricional { margin:0; text-align:center; font-size:14px; font-weight:500; }.frase-apoio-tabela-nutricional { width:100%; max-width:756px; margin:8px auto 0; font-size:14px; line-height:1.4; text-align:left; }.tabela-dados.tabela-nutricional td { width:auto; text-align:center; box-sizing:border-box; }.tabela-dados.tabela-nutricional td:nth-child(2), .tabela-dados.tabela-nutricional td:nth-child(3) { width:22%; }.tabela-dados.tabela-nutricional .linha-cabecalho-nutricional td { background:#e8efeb !important; color:#173a35; text-align:center !important; font-weight:700; } INFORMAÇÃO NUTRICIONAL Porção: 40g (1 unidade) Porção (100g)* Porção (40g) Valor energético (kcal) 252,5 101 Carboidratos (g) 47,5 19 Proteínas (g) 9,3 3,7 Fibras alimentares (g) 6,8 2,7 Sódio (mg) 505 202 *As informações nutricionais foram calculadas automaticamente com base em 100g do produto e podem apresentar pequenas variações em relação às informações constantes na embalagem do fabricante. Antes do consumo, confira sempre as informações nutricionais e a lista de ingredientes na embalagem original do produto. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
