INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (366, 'Pão de Forma de Leite Seven Boys 450g', 'pão de forma de leite seven boys 450g', 'Seven Boys', 1.0, '450g', 'leites', '/images/produtos/1010591_39e197a85054.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Pão de Forma de Leite, da marca Seven Boys, em embalagem com 450 gramas. É um produto conhecido por sua textura macia e sabor leve e ligeiramente adocicado, devido ao leite e ao açúcar na receita. Sua textura é macia e fofinha, com miolo delicado e uma crosta suave. Pode ser usado para uma ampla gama de preparações, como sanduíches, torradas, bruschettas e, até mesmo, como base para receitas mais elaboradas, como pudim de pão. Por ser pré-fatiado, o pão de forma é conveniente e pronto para uso, economizando tempo na cozinha. É uma escolha prática e deliciosa para quem busca um pão macio e saboroso, ideal para uma variedade de usos na cozinha. Sua porção com 50 gramas possui valor energético de 131 kcal, 26 gramas de carboidratos e 4,8 gramas de proteínas e 194 miligramas de sódio. Para melhor conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência direta de luz. INGREDIENTES: Farinha de trigo enriquecida com ferro e ácido fólico, açúcar, óleo de soja, sal, leite em pó desnatado, conservadores propionato de cálcio e ácido sórbico e aromatizante. ALÉRGICOS: Contém derivados de trigo, soja e leite. pode conter amêndoa, amendoim, aveia, avelãs, castanha-de-caju, castanha-do-pará, centeio, cevada, macadâmias, nozes, ovos, pecãs, pistaches e triticale. Descrição do Produto .index-selos { display: flex; } .grupo1, .grupo2 { display: flex; max-width: 300px; } .selo { width: 100%; text-align:center; background-color: transparent; border: 1px solid transparent; padding: 15px 15px; } .selo img { width: 100px; } .selo p { font-weight: bold; font-size: 12px; text-transform: uppercase; } @media screen and (min-width: 320px) and (max-width:1023px) { .index-selos { flex-direction: column; } .grupo1 { width: 100%; } } Contém Glúten Contém Lactose') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
