INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (368, 'Pão Mini Cacetinho Pão Francês Zaffari', 'pão mini cacetinho pão francês zaffari', 'Zaffari', 1.0, '1 un', 'mercearia', '/images/produtos/1003819_80558e05e859.jpg', 'Pão Francês Cacetinho Mini, da marca Zaffari, vendido em unidade ou por peso. Produto também conhecido como pão de sal, pão de trigo ou pão d''água, é perfeito para quem busca praticidade e sabor. Não contém lactose , sendo uma opção adequada para diferentes preferências de consumo. Devido a seu tamanho menor, ele é ideal para lanches rápidos acompanhamentos diversos ou para compor uma cesta de café da manhã . Com textura crocante por fora e interior macio, este pão é uma excelente escolha por sua versatilidade. Pode ser consumido puro ou com diversos acompanhamentos de acordo com padrões desejados, como manteiga, geleia, pastas de amendoim, ovos mexidos, frios, queijos ou como acompanhamento de sopas e saladas compondo receitas como croûton. Além disso, seu formato compacto facilita o consumo individual e o controle de porções, tornando-o uma escolha prática para o dia a dia e para diferentes momentos de consumo. Sua porção de 40 gramas possui valor energético de 107 kcal, 3,1 gramas de proteínas, 22,5 gramas de carboidratos, 0,3 grama de gorduras totais e 219 miligramas de sódio . Para conservação do produto, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta. INGREDIENTES: Farinha de trigo enriquecida com ferro e ácido fólico, sal, óleo de soja e fermento biológico. ALÉRGICOS: Contém glúten. Não contém lactose. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Glúten Sem Lactose Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
