INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (369, 'Pão Francês Folhado com Parmesão Zaffari', 'pão francês folhado com parmesão zaffari', 'Zaffari', 1.0, '1 un', 'mercearia', '/images/produtos/1120378_524f0ca1d8ab.jpg', 'Pão Francês Folhado com Parmesão, da marca Zaffari, vendido por unidade e peso. É uma releitura saborosa do clássico pão francês, com um toque sofisticado do parmesão na superfície que adiciona um sabor marcante e levemente salgado , com notas intensas e um leve toque amanteigado. Ideal para compor cafés da manhã especiais, brunches, lanches da tarde ou refeições rápidas, este pão pode ser servido puro ou acompanhado por manteiga, requeijão, cream cheese, geleias artesanais e patês variados. Também harmoniza perfeitamente com queijos, presuntos, peito de peru, salame, copa e outros embutidos. Em preparações mais elaboradas, pode ser utilizado para criar sanduíches gourmet com rosbife, rúcula e queijo brie, mini bruschettas, torradas crocantes para entradas ou até mesmo acompanhamentos para tábuas de frios. Para harmonização de bebidas, combina muito bem com café coado, espresso, cappuccino, chocolate quente, chá preto, chá de ervas, suco natural de laranja e suco de uva integral. Por ser vendido por peso , permite adquirir a quantidade ideal para diferentes necessidades, seja para o consumo diário da família ou para encontros especiais. Para manter a qualidade e a crocância por mais tempo, recomenda-se conservar o produto em local seco, fresco e protegido da luz solar direta. Se necessário, pode ser aquecido rapidamente no forno para recuperar o aroma e a textura recém-assada. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Glúten Contém Lactose Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
