INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (370, 'Pão de Forma Integral Zaffari 450g', 'pão de forma integral zaffari 450g', 'Zaffari', 1.0, '450g', 'mercearia', '/images/produtos/1102724_1499392bb8af.jpg', 'Pão de Forma Integral, da marca Zaffari, em embalagem com 450g. Produzido com uma combinação cuidadosa de ingredientes, ele se destaca por sua composição com 39,2% de farinha integral, proporcionando uma opção mais nutritiva em comparação aos pães tradicionais. Sua textura macia e levemente aerada permite diversas combinações ao longo das refeições. Ideal para compor desde o café da manhã até lanches intermediários ou refeições rápidas . No início do dia, pode ser servido com manteiga, geleias, mel ou acompanhado de frutas frescas, criando uma refeição equilibrada. Para quem prefere opções salgadas , combina perfeitamente com queijos, peito de peru, ovos mexidos ou pastas como homus e creme de ricota. É uma ótima base para sanduíches naturais recheados com frango desfiado, cenoura ralada e folhas verdes. Outra sugestão é utilizá-lo no preparo de tostadas crocantes com abacate e ovo pochê. Também pode ser transformado em deliciosos mistos quentes, baurus ou até mesmo em receitas como rabanadas integrais e tortas salgadas de forno. Sua composição contribui para uma alimentação mais equilibrada , sendo uma fonte de fibras que auxiliam no bom funcionamento do organismo. Este pão é um alimento integral que se encaixa perfeitamente em diferentes estilos alimentares, oferecendo uma opção saborosa para quem deseja manter uma rotina mais saudável. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Glúten Integral Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
