INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (372, 'Pão de Queijo Pré-assado para Air Fryer Congelado Forno de Minas 400g', 'pão de queijo pré-assado para air fryer congelado forno de minas 400g', 'Forno de Minas', 1.0, '400g', 'leites', '/images/produtos/1111933_7af3d945d8ac.jpg', 'Pão de Queijo Pré-assado para Air Fryer Congelado, da marca Forno de Minas, em embalagem com 400 gramas. Inspirado na tradição da culinária mineira, este produto reúne praticidade e muito sabor em uma receita desenvolvida para proporcionar um preparo rápido , sem deixar de lado as características que fazem do pão de queijo um dos alimentos mais apreciados. Sua textura macia e o sabor intenso do queijo transformam qualquer momento em uma pausa especial, seja para receber visitas ou simplesmente desfrutar de um café fresco em casa, ou em ocasiões especiais, pode compor tábuas de café colonial, brunches ou mesas de confraternização. Por ser sem glúten , este pão de queijo é uma excelente alternativa para pessoas que seguem uma alimentação, seja por restrição alimentar ou por preferência. Pode ser servido puro ou acompanhado por manteiga, requeijão, cream cheese, geleias, doce de leite ou mel, criando diferentes combinações para o café da manhã e o lanche, também harmoniza perfeitamente com cafés especiais, cappuccinos, chocolates quentes, chás e sucos naturais. Sua porção de 50 gramas (aproximadamente 4 unidades) possui valor energético de 171 kcal , 26 gramas de carboidratos , 3,5 gramas de proteínas , 5,8 gramas de gorduras totais e 249 miligramas de sódio . INGREDIENTES: Polvilho azedo, queijo, óleo vegetal, água, ovos, leite integral, amido modificado, sal e aroma natural de queijo. ALÉRGICOS: Contém leite e ovos. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Pré-Pronto Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
