INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (373, 'Batata Palito Pré-frita Extra Crocante Congelada McCain 600g', 'batata palito pré-frita extra crocante congelada mccain 600g', 'McCain', 1.0, '600g', 'mercearia', '/images/produtos/1101505_982995eaa17d.jpg', 'Batata Palito Congelada Extra Crocante, da marca McCain, em embalagem com 600 gramas. Apresenta-se como uma solução prática e saborosa para diversas ocasiões, destacando-se pela sua textura extra crocante e corte fino, ideal para quem busca agilidade no preparo sem abrir mão de uma batata frita perfeita. Desenvolvida especialmente para o uso em air fryer , este produto promete resultados superiores, mantendo a crocância desejada com menos óleo. O preparo rápido é um dos seus grandes atrativos, com um tempo estimado de apenas 8 minutos na air fryer, tornando-se uma excelente opção para lanches rápidos, acompanhamentos de refeições ou até mesmo como petisco em reuniões com amigos e familiares. A praticidade que este item oferece se estende desde o armazenamento até o consumo, simplificando a rotina de quem tem um dia a dia agitado. É um item versátil que pode ser combinado com diversos molhos e pratos, enriquecendo qualquer refeição. A sua textura crocante e o corte fininho são características que a diferenciam no mercado, oferecendo um aperitivo irresistível. A embalagem de 600 gramas é ideal para famílias ou para quem aprecia ter este delicioso acompanhamento sempre à mão. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (373, 6, 18.98, CURRENT_TIMESTAMP, 'zaffari', 'Batata Palito Pré-frita Extra Crocante Congelada McCain 600g', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (374, 'Ervilha Congelada Naturale 300g', 'ervilha congelada naturale 300g', 'Naturale', 1.0, '300g', 'mercearia', '/images/produtos/1089621_5411fd34cba0.jpg', 'Ervilha Congelada, da marca Naturale, em embalagem com 300 gramas. Colhidas no ponto ideal de frescor e rapidamente congeladas para preservar todos os nutrientes, essas ervilhas são uma excelente escolha para quem busca conveniência sem abrir mão da qualidade. O processo de congelamento rápido preserva as características originais das ervilhas, como cor, textura e sabor, além de seus valiosos nutrientes . Isso significa que, ao preparar as refeições, é possível desfrutar de um vegetal com qualidade. Pode ser incorporada em saladas, acompanhamentos, sopas, refogados, tortas e uma infinidade de pratos. Sua presença adiciona um toque de cor vibrante e um sabor adocicado aos paladares. Sendo 100% natural, o produto reforça o compromisso com a qualidade e a ausência de conservantes artificiais, tornando-o uma escolha confiável para o congelador. A facilidade de preparo é outro ponto forte: basta adicionar às receitas, sem a necessidade de descascar ou picar. É um ingrediente prático para o dia a dia corrido, que contribui para uma alimentação equilibrada e saborosa. A incorporação deste vegetal congelado na dieta é uma maneira simples de enriquecer as refeições com sabor e saúde. Sua porção de 130 gramas (1 xícara de chá) possui valor energético de 77 kcal, 11,7 gramas de carboidratos, 6,8 gramas de proteínas, 0,4 grama de gorduras totais, 6 gramas de fibra alimentar e 43,2 miligramas de sódio. Para melhor conservação, recomenda-se manter o produto armazenado no freezer. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Pré-Pronto Vegetal Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
