INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (375, 'Pão de Queijo Tradicional Congelado Tutti Giorni 400g', 'pão de queijo tradicional congelado tutti giorni 400g', 'Tutti Giorni', 1.0, '400g', 'leites', '/images/produtos/1088246_f23969a0d577.jpg', 'Pão de Queijo Tradicional Congelado, da marca Tutti Giorni, em embalagem com 400 gramas. O produto combina a praticidade do preparo congelado com o sabor marcante do queijo . Ao sair do forno, o aroma característico se espalha pela cozinha e convida para uma experiência acolhedora, enquanto a casquinha dourada contrasta com o centro macio , característica que faz do pão de queijo uma escolha apreciada no café da manhã, no lanche da tarde ou como acompanhamento em diferentes ocasiões. O produto pode ser levado diretamente ao forno ou preparado na air fryer , proporcionando diferentes possibilidades para chegar ao ponto desejado. Servido ainda quente, combina muito bem com café passado, cappuccino, chá ou sucos, compondo um lanche simples e saboroso. Na cozinha, o pão de queijo pode ganhar novos acompanhamentos e apresentações. Uma sugestão é servi-lo com requeijão cremoso, geleia de frutas, doce de leite ou manteiga, criando contrastes entre o sabor salgado do queijo e notas mais doces. Sua porção de 50 gramas possui valor energético de 124 kcal, 16 gramas de carboidratos, 1,5 grama de proteínas, 6 gramas de gorduras totais e 290 miligramas de sódio . A embalagem com 400 gramas facilita o armazenamento e permite preparar somente a quantidade desejada, mantendo o restante congelado para outras ocasiões. Para a conservação, o produto deve permanecer congelado a -12ºC, conforme as orientações da embalagem. INGREDIENTES: Polvilho, gordura vegetal, queijo parmesão, ovos. ALÉRGICOS: Contém lactose, ovos e derivados de leite. Pode conter traços de soja. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Lactose Pré-Pronto .tabela-dados { width:100%; max-width:756px; border-collapse:collapse; margin:0 auto; color:#242424; }.tabela-dados td { padding:6px; height:51px; width:50%; vertical-align:middle; }.tabela-dados tr:nth-child(even) td { background-color:#ffffff; }.tabela-dados tr:nth-child(odd) td { background-color:#f5f7f5;}.tabela-dados td:first-child { text-align:right; font-weight:bold; }.cabecalho-tabela-nutricional { width:100%; max-width:756px; margin:6px auto 6px; color:#173a35; }.titulo-tabela-nutricional { margin:0; text-align:center; font-size:18px; font-weight:700; text-transform:uppercase; }.porcao-tabela-nutricional { margin:0; text-align:center; font-size:14px; font-weight:500; }.frase-apoio-tabela-nutricional { width:100%; max-width:756px; margin:8px auto 0; font-size:14px; line-height:1.4; text-align:left; }.tabela-dados.tabela-nutricional td { width:auto; text-align:center; box-sizing:border-box; }.tabela-dados.tabela-nutricional td:nth-child(2), .tabela-dados.tabela-nutricional td:nth-child(3) { width:22%; }.tabela-dados.tabela-nutricional .linha-cabecalho-nutricional td { background:#e8efeb !important; color:#173a35; text-align:center !important; font-weight:700; } INFORMAÇÃO NUTRICIONAL Porção: 50g Porção (100g)* Porção (50g) Valor energético (kcal) 248 124 Carboidratos (g) 32 16 Proteínas(g) 3 1,5 Gorduras totais (g) 12 6 Sódio (mg) 580 290 *As informações nutricionais foram calculadas automaticamente com base em 100g do produto e podem apresentar pequenas variações em relação às informações constantes na embalagem do fabricante. Antes do consumo, confira sempre as informações nutricionais e a lista de ingredientes na embalagem original do produto. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
