INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (376, 'Pão de Queijo Tradicional Congelado Tutti Giorni 1kg', 'pão de queijo tradicional congelado tutti giorni 1kg', 'Tutti Giorni', 1.0, '1kg', 'leites', '/images/produtos/1088105_2ecc8001c6fc.jpg', 'Pão de Queijo Tradicional Congelado, da marca Tutti Giorni, em embalagem com 1 quilo. Produzido com queijo parmesão maturado , este clássico da culinária brasileira entrega uma experiência autêntica. Sua combinação de ingredientes resulta em um pão de queijo com casquinha levemente crocante por fora e interior macio e extremamente saboroso. Pensado para facilitar a rotina, o produto se destaca pela praticidade no preparo. Por estar congelado, mantém suas características por mais tempo, garantindo sua qualidade . Basta levar ao forno pré-aquecido para que, em poucos minutos, esteja pronto para consumo, liberando um aroma irresistível que remete ao aconchego da cozinha caseira. Com rendimento generoso, a embalagem de 1kg atende desde refeições em família até encontros com amigos, sendo uma excelente escolha para cafés da manhã, lanches da tarde ou até mesmo como acompanhamento em mesas mais completas. Além disso, por ser sem glúten , amplia seu consumo para pessoas com restrições alimentares . Pode ser servido recheado com requeijão cremoso, doce de leite ou goiabada, criando combinações que equilibram o salgado e o doce. Também pode ser utilizado como base para mini sanduíches, acompanhando ingredientes como peito de peru, queijo, frango desfiado ou até versões vegetarianas, com legumes grelhados. Em ocasiões descontraídas, pode compor tábuas de petiscos ao lado de frios e pastas. Outra ideia interessante é utilizá-lo como complemento em cafés mais elaborados, harmonizando perfeitamente com bebidas quentes como café fresco ou cappuccino. ALÉRGICOS: Contém lactose, derivados de leite e de ovos. Pode conter soja. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Lactose Pré-Pronto Sem Glúten Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (376, 6, 19.98, CURRENT_TIMESTAMP, 'zaffari', 'Pão de Queijo Tradicional Congelado Tutti Giorni 1kg', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (377, 'Vegetais para Sopa Congelados Naturale 300g', 'vegetais para sopa congelados naturale 300g', 'Naturale', 1.0, '300g', 'mercearia', '/images/produtos/1081372_4324b6d0b4ec.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Vegetais Congelados para Sopa, da marca Naturale, em embalagem com 300 gramas. Pré-selecionados e higienizados, já vem picados para auxiliar seu uso nos preparos. São a escolha prática e saudável para preparar refeições nutritivas em qualquer ocasião. Com uma seleção de vegetais frescos e variados, prontos para uso, este mix é ideal para sopas, caldos, ensopados e até mesmo para enriquecer outros pratos, como risotos e massas. O alimento, que é 100% natural, combina cenoura, alho-poró, couve-flor, aipo, salsão, ervilha, couve de Bruxelas, abobrinha e brócolis. Ele é perfeito para adicionar nutrientes a alimentação diária, de forma prática. São ideais para refeições reconfortantes em dias mais frios, ou para uma alimentação leve e equilibrada em qualquer época do ano. Podem ser usados em jantares rápidos ou em almoços mais elaborados. Para acompanhar essa refeição nutritiva, opte por vinhos brancos leves ou um suco natural de frutas. Pães integrais ou torradas também são ótimos acompanhamentos para a sopa, proporcionando uma refeição completa e saborosa. O produto deve ser mantido no congelador para manter a qualidade. Descrição do Produto .index-selos { display: flex; } .grupo1, .grupo2 { display: flex; max-width: 300px; } .selo { width: 100%; text-align:center; background-color: transparent; border: 1px solid transparent; padding: 15px 15px; } .selo img { width: 100px; } .selo p { font-weight: bold; font-size: 12px; text-transform: uppercase; } @media screen and (min-width: 320px) and (max-width:1023px) { .index-selos { flex-direction: column; } .grupo1 { width: 100%; } } Vegetal Natural') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
INSERT INTO preco (produto_id, mercado_id, valor, coletado_em, origem, nome_bruto, disponivel) VALUES (377, 6, 3.95, CURRENT_TIMESTAMP, 'zaffari', 'Vegetais para Sopa Congelados Naturale 300g', TRUE);
INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (378, 'Chicken Crocante de Frango Empanado Congelado Nat 300g', 'chicken crocante de frango empanado congelado nat 300g', 'Nat', 1.0, '300g', 'carnes', '/images/produtos/1130835_cc897f7aa05e.jpg', 'Frango Empanado Chicken Croc Congelado, da marca Nat, em embalagem com 300 gramas. Este produto congelado oferece uma experiência saborosa e prática para quem busca uma refeição rápida e deliciosa. Elaborado com 100% peito de frango , garante uma fonte de proteína significativa, ideal para compor pratos equilibrados. A cobertura crocante, resultado de um empanamento cuidadoso, proporciona uma textura irresistível a cada mordida. Além disso, a formulação utiliza 100% temperos naturais . A ausência de antibióticos no processo de produção confere um diferencial importante. A versatilidade é um dos grandes atrativos deste frango empanado. Sua previsão de preparo é de apenas 10 minutos , sendo uma excelente opção para o almoço, jantar ou um lanche especial. A praticidade se estende ao preparo na Air Fryer, método que resulta em um produto ainda mais sequinho e crocante, mantendo todas as suas qualidades. A embalagem de 300 gramas é perfeita para porções individuais ou para compartilhar em momentos casuais. Cada porção contribui com 18 gramas de proteína , auxiliando na saciedade e no aporte nutricional. É um produto que reforça a rapidez e facilidade de preparo, ideal para a rotina agitada. O sabor é um convite à celebração, com uma combinação que agrada a diversos paladares. A qualidade dos ingredientes e o cuidado no processamento resultam em um alimento que une sabor, praticidade e bem-estar, tornando-se um item indispensável no dia a dia. Este frango empanado é uma escolha ideal para quem valoriza alimentação prática e saborosa. Para conservação do produto, deve ser mantido no congelador até a ocasião de consumo. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
