INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (379, 'Iscas de Frango Empanadas Congelado Nat 300g', 'iscas de frango empanadas congelado nat 300g', 'Nat', 1.0, '300g', 'carnes', '/images/produtos/1130833_ff0ce35f8492.jpg', 'Iscas de Frango Empanadas Congeladas, da marca Nat, em embalagem com 300 gramas. Estas deliciosas iscas representam uma opção prática e saborosa para refeições rápidas e lanches. Elaboradas com 100% peito de frango , garantem uma fonte de proteína para as refeições, ideal para quem busca uma alimentação equilibrada sem abrir mão do prazer de comer bem. Nelas, contém temperos 100% naturais , conferindo um sabor autêntico e agradável. Livre de antibióticos, o produto reforça o compromisso com a saúde e o bem-estar. O preparo é incrivelmente simples e rápido, podendo ser feito em apenas 16 minutos na Air Fryer, resultando em uma crocância irresistível e um interior suculento. Essa característica torna as iscas de frango empanadas uma escolha excelente para o dia a dia corrido, oferecendo uma refeição pronta em pouco tempo. Com 22 gramas de proteína por porção , é uma alternativa nutritiva para diversas ocasiões, desde um petisco para receber amigos até um acompanhamento versátil para saladas ou outros pratos. A embalagem de 300 gramas é ideal para famílias pequenas ou para quem deseja ter sempre à mão uma opção prática. O empanado crocante e o recheio macio criam uma combinação irresistível que agrada a todos os paladares. A praticidade de congelados como este facilita a rotina, garantindo sabor e nutrição. Para conservação do produto, deve ser mantido no congelador até a ocasião de consumo. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Carne de Aves Carne Branca Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
