INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (380, 'Hambúrguer Bovino Congelado Sadia 113g', 'hambúrguer bovino congelado sadia 113g', 'Sadia', 1.0, '113g', 'mercearia', '/images/produtos/1123137_5614d72d3439.jpg', 'Hambúrguer Bovino Congelado, da marca Sadia, em embalagem com 113 gramas. É uma excelente opção para quem busca praticidade e sabor na hora de preparar refeições rápidas e deliciosas. Produzido com carne bovina selecionada, o produto garante suculência e textura macia após o preparo, seja na grelha, frigideira ou air fryer. Ideal para compor lanches personalizados, esse hambúrguer permite criar combinações criativas com queijos, molhos, saladas e pães variados, proporcionando uma experiência gastronômica digna de hamburgueria, sem sair de casa. Além de versátil, o hambúrguer congelado é uma alternativa prática para o dia a dia corrido, pois já vem porcionado e pronto para o preparo, exigindo apenas alguns minutos para atingir o ponto ideal. Pode ser armazenado no congelador por longos períodos sem perder suas características originais, o que o torna uma boa escolha para manter no freezer e utilizar quando necessário. É indicado tanto para refeições individuais quanto para ocasiões especiais, como encontros com amigos ou jantares informais. Para um resultado ainda mais saboroso, recomenda-se descongelar levemente antes de grelhar e temperar de acordo com a preferência. O hambúrguer Sadia é um item indispensável para quem aprecia soluções práticas, sem abrir mão da qualidade e do sabor característico da boa carne bovina.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
