INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (381, 'Leite UHT Integral Parmalat 1 Litro', 'leite uht integral parmalat 1 litro', 'Parmalat', 1.0, '1 l', 'leites', '/images/produtos/1087590_1deb1bf03c1e.jpg', 'Leite Integral UHT, da marca Parmalat, em caixa com 1 litro. É um leite integral submetido ao processo de ultra alta temperatura (UHT) que garante sua conservação por mais tempo sem a necessidade de refrigeração antes de aberto. Seu aroma é delicado e característico, remetendo à pureza do leite fresco. Pode ser usado em uma infinidade de receitas, como bolos, pudins, molhos, vitaminas e doces diversos, além de ser excelente para o preparo de cafés e cappuccinos cremosos. Também fica delicioso acompanhado de cereais crocantes, granolas, pães variados, torradas, bolos caseiros e frutas frescas, criando composições cheias de sabor. É perfeito para o consumo em diferentes momentos do dia, seja no café da manhã, lanche da tarde ou mesmo como um ingrediente em refeições mais elaboradas. Também é perfeito para ser combinado com cereais, pães, frutas e achocolatados, proporcionando uma experiência completa e nutritiva. Para a conservação do produto, é recomendado que ele seja armazenado em local seco e fresco, longe da incidência de luz solar direta. Após aberto, deve ser mantido sob refrigeração, seguindo as instruções da embalagem. INGREDIENTES: Leite integral e estabilizantes (citrato de sódio, trifosfato de sódio, monofosfato de sódio e difosfato de sódio). ALÉRGICOS: Contém lactose e leite. Pode conter soja. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Lactose Integral Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
