INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (382, 'Leite UHT Semidesnatado Santa Clara 1 Litro', 'leite uht semidesnatado santa clara 1 litro', 'Santa Clara', 1.0, '1 l', 'leites', '/images/produtos/1017571_c8c9ce965bef.jpg', 'Leite UHT Semidesnatado, da marca Santa Clara, em caixa com 1 litro. Pensado para quem busca equilíbrio entre leveza e nutrição . Este leite é uma excelente escolha para compor uma rotina alimentar, oferecendo uma alternativa intermediária entre o integral e o desnatado. Sua embalagem de 1 litro atende bem a diferentes necessidades de consumo, trazendo praticidade para a rotina. Produzido com a tecnologia UHT (Ultra High Temperature), ele passa por um processo que assegura maior durabilidade, preservando suas características nutricionais e permitindo armazenamento fora da geladeira antes de aberto. O resultado é um alimento que atende a diferentes perfis de consumo, sendo uma escolha equilibrada para quem deseja reduzir a ingestão de gordura. No dia a dia, pode ser consumido puro, com café ou combinado com cereais. Também é uma excelente base para receitas como vitaminas, smoothies, mingau, panquecas e bolos. Ainda contribui para preparações salgadas, em molhos brancos, cremes, sopas e purês de batata ou moranga. Além disso, é fonte de cálcio , essencial para a manutenção dos ossos, e de proteínas , importantes para funções estruturais do organismo. O Leite UHT Semidesnatado Santa Clara é uma opção prática tanto para o café da manhã quanto para lanches e receitas ao longo do dia. ALÉRGICOS: Contém lactose. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Lactose Semidesnatado p.borda {border-radius: 8px;padding: 20px;background: #f5f7f5;text-align: center;} O MINISTÉRIO DA SAÚDE INFORMA: O ALEITAMENTO MATERNO EVITA INFECÇÕES E ALERGIAS E É RECOMENDADO ATÉ OS 2 (DOIS) ANOS DE IDADE OU MAIS. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
