INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (383, 'Leite UHT Integral Santa Clara 1 Litro', 'leite uht integral santa clara 1 litro', 'Santa Clara', 1.0, '1 l', 'leites', '/images/produtos/1017551_a4887514f961.jpg', 'Leite UHT Integral, da marca Santa Clara, em caixa com 1 litro. Este clássico do dia a dia se destaca pela qualidade e sabor . Produzido por meio da tecnologia UHT (Ultra High Temperature), o leite passa por um processo térmico que assegura maior durabilidade sem a necessidade de refrigeração antes de aberto, preservando suas propriedades nutricionais. Com sua composição integral , contendo aproximadamente 3% de gorduras, apresenta uma textura naturalmente mais cremosa e um sabor encorpado. Seja puro, com café ou como ingrediente culinário, o Leite UHT Integral entrega um alimento nutritivo e saboroso. Ele pode ser utilizado no preparo de receitas como bolos fofinho, arroz doce tradicional e panquecas macias. Em pratos salgados, é essencial para um purê de batatas aveludado, molho branco para massas, lasanhas e suflês. Também combina perfeitamente com vitaminas de frutas, cafés especiais e achocolatados, enriquecendo o café da manhã ou o lanche da tarde. Além do sabor, o leite integral é uma importante fonte de cálcio , contribuindo para a saúde óssea, além de fornecer proteínas e vitaminas essenciais para o funcionamento do organismo. O Leite UHT Integral Santa Clara é uma escolha confiável para quem busca nutrição e praticidade em um único produto. A embalagem de 1 litro é prática e ideal para o consumo familiar. ALÉRGICOS: Contém lactose. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Contém Lactose Fresco (Laticínios) Integral p.borda {border-radius: 8px;padding: 20px;background: #f5f7f5;text-align: center;} O MINISTÉRIO DA SAÚDE INFORMA: O ALEITAMENTO MATERNO EVITA INFECÇÕES E ALERGIAS E É RECOMENDADO ATÉ OS 2 (DOIS) ANOS DE IDADE OU MAIS. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
