INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (384, 'Queijo Mussarela Fatiado Président 300g', 'queijo mussarela fatiado président 300g', 'Président', 1.0, '300g', 'leites', '/images/produtos/1091455_dbee3ad6a1a6.jpg', 'Queijo Mussarela Fatiado, da marca Président, em embalagem com 300 gramas. Este latcínio oferece praticidade e sabor para o dia a dia. Com fatias fininhas e uniformes, é versátil para preparar diversas receitas. A embalagem mantém o frescor do produto, e sua textura macia e sabor suave acompanham muito bem sanduíches, torradas, tapiocas e até mesmo para ser consumido puro, como um lanche rápido e nutritivo. As fatias já vêm prontas para uso, economizando tempo na cozinha e facilitando a montagem de pratos. É um excelente aliado para quem busca praticidade sem abrir mão da qualidade e do bom gosto. A versão fatiada se torna ainda mais fácil de ser consumida, e a sua versatilidade permite que o queijo seja incorporado em receitas quentes e frias, adicionando um toque especial e delicioso. O laticínio é uma fonte de cálcio e proteínas, agregando valor nutricional às suas receitas. Também pode ser utilizado para derreter em pizzas, lasanhas e outros pratos italianos, garantindo aquele toque especial . Harmoniza bem com vinhos brancos e cervejas leves. Sua porção de 40 gramas (2 fatias) possui valor energético de 127 kcal, 1 grama de carboidratos, 9,6 gramas de proteínas, 9,3 gramas de gorduras totais e 188 miligramas de sódio. Recomenda-se manter o produto em pote com tampa e sob refrigeração. INGREDIENTES: Leite pasteurizado, cloreto de sódio (sal), cloreto de cálcio, fermento lácteo, coagulante, regulador de acidez ácido cítrico e conservador natamicina. ALÉRGICOS: Contém lactose e derivados de leite. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Fatiado Contém Lactose Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
