INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (385, 'Leite UHT Semidesnatado Zero Lactose Zymil Parmalat 1 Litro', 'leite uht semidesnatado zero lactose zymil parmalat 1 litro', 'Parmalat', 1.0, '1 l', 'leites', '/images/produtos/1066539_16adaa19756c.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Leite Semidesnatado Zymil Zero Lactose UHT, da marca Parmalat, em embalagem com 1 litro. É a escolha ideal para quem busca uma alimentação leve e saudável sem abrir mão do sabor. Com 3x menos gordura que o leite integral, este leite semidesnatado é perfeito para dietas balanceadas e, por ser zero lactose, é ideal para pessoas intolerantes à lactose ou que preferem evitar este açúcar natural do leite. Seu processamento UHT garante maior durabilidade, mantendo o sabor e os nutrientes por mais tempo. Este leite é extremamente versátil e pode ser utilizado em diversas receitas, desde o preparo de café, chá e smoothies, até sobremesas como pudins e bolos. É perfeito para acompanhar cereais matinais, granolas e frutas, oferecendo uma combinação equilibrada de nutrientes para começar bem o dia. Sua porção de 200 mililitros (1 copo) possui valor energético de 78 kcal, 9 gramas de carboidratos, 9 gramas de açúcares totais, 2 gramas de gorduras totais, 210 miligramas de cálcio e 130 miligramas de sódio. INGREDIENTES: Leite semidesnatado, enzima lactase e estabilizantes (citrato de sódio, trifosfato de sódio, monofosfato de sódio e difosfato de sódio).') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
