INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (388, 'Iogurte Grego Tradicional Vigor 90g', 'iogurte grego tradicional vigor 90g', 'Vigor', 1.0, '90g', 'leites', '/images/produtos/1099346_bdd20c2d8d22.jpg', 'Iogurte Grego Tradicional, da marca Vigor, em embalagem com 90 gramas. É a escolha perfeita para quem busca uma opção equilibrada, cremosa e deliciosa. Com uma textura densa e sabor inigualável, ele pode ser consumido puro ou combinado com diversos alimentos e bebidas para enriquecer ainda mais as dietas. Perfeito para uma pausa no meio do dia, pode ser consumido puro ou com sementes e nuts para um toque crocante. Pode ser utilizado como base para sobremesas leves e saborosas, como parfaits ou até mesmo como um substituto leve para cremes em receitas. Frutas frescas, como morangos, blueberries e bananas, são ótimas opções para complementar. Granolas, cereais, sementes como chia e linhaça, mel, geleias naturais e nuts, como amêndoas e nozes, também combinam perfeitamente. Em sua porção de 90 gramas(1 unidade), contém valor energético de 139 kcal, 14 gramas de carboidratos, 13 gramas de açúcares totais, 5 gramas de proteínas, 7 gramas de gorduras totais e 37 miligramas de sódio . Para garantir a máxima qualidade e frescor do iogurte, mantenha-o sob refrigeração. Após aberto, deve ser consumido imediatamente. INGREDIENTES: Leite integral e/ou leite integral reconstituído, concentrado proteico de leite, açúcar líquido, creme de leite, amido modificado, fermento lácteo e estabilizante gelatina. ALÉRGICOS: Contém leite e derivados. Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
