INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (390, 'Leite UHT Semidesnatado Parmalat 1 Litro', 'leite uht semidesnatado parmalat 1 litro', 'Parmalat', 1.0, '1 l', 'leites', '/images/produtos/1087602_be7b9fff900f.jpg', 'p.borda2 { border-width: 2px; border-style: solid; border-color: #424242; padding: 20px; } Leite Semidesnatado UHT, da marca Parmalat, em embalagem com 1 litro. É um leite que passa pelo processo de ultra alta temperatura (UHT), permitindo sua conservação por longos períodos fora da geladeira antes de ser aberto, sem perder suas qualidades nutricionais. Com menos gordura do que o leite integral, ele mantém um sabor suave e equilibrado, ideal para quem busca uma opção mais leve, sem precisar abrir mão do prazer de consumir leite. Sua textura é levemente fluida, proporcionando uma sensação agradável ao paladar, e seu aroma é delicado, com notas que remetem à pureza e frescor. É uma escolha versátil para diversas receitas, como sobremesas, molhos e preparações leves, além de ser uma ótima base para bebidas como cafés, chás e smoothies. Pode ser consumido em qualquer momento do dia, especialmente no café da manhã e da tarde, assim como na hora de dormir, quando um copo de leite pode ser muito bem-vindo. Harmoniza bem com cereais, pães integrais, frutas e achocolatados, oferecendo uma experiência nutritiva e saborosa. Em sua porção de 200 mililitros (1 copo) contém 78 kcal, 9 gramas de carboidratos, 6 gramas de proteínas e 130 miligramas de sódio. Para conservação do produto, é recomendado que seja armazenado em local seco e fresco, longe da incidência de luz solar direta. Após aberto, manter sob refrigeração, seguindo as instruções da embalagem. INGREDIENTES: Leite semidesnatado e estabilizantes (citrato de sódio, trifosfato de sódio, monofosfato de sódio e difosfato de sódio). ALÉRGICOS: Contém leite. Pode conter soja. Descrição do Produto .index-selos { display: flex; } .grupo1, .g