INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (391, 'Batata-branca', 'batata-branca', 'Hortifrutigranjeiros', 1.0, '1 un', 'mercearia', '/images/produtos/1001669_c9e44418a266.jpg', 'Batata-branca, vendida em unidade ou por peso. É um alimento versátil, com casca fina e polpa clara, que apresenta uma textura macia e um sabor suave , sendo um ingrediente prático e fundamental para o preparo de diversas receitas, muito utilizada na culinária tradicional. Sua versatilidade permite diferentes métodos de cozimento, seja assada, cozida ou frita. A batata branca é reconhecida por sua capacidade de absorver temperos, realçando o sabor de pratos principais como uma opção de acompanhamentos. É uma fonte natural de vitaminas e carboidratos, que traz energia e saciedade , sendo benéfica para a saúde. É considerada uma estrela entre as receitas clássicas, como batatas rústicas assadas com ervas, gratinadas, temperada, com bacon e requeijão, além de ser um acompanhamento popular para carnes, aves e lanches. Em saladas, oferece uma textura agradável e um sabor que complementa outros ingredientes. Também se adapta a receitas diárias e preparos mais elaborados, podendo ser usada em sopas cremosas, escondidinhos e até mesmo como base para massas e recheios. Produto de fácil preparo , é uma opção econômica e nutritiva para o dia a dia, assegurando a qualidade necessária para elevar o nível das refeições. Sua aparência uniforme e tamanho médio facilitam o manuseio e o cozimento homogêneo, garantindo resultados consistentes na cozinha. Por ser um ingrediente de fácil combinação, adapta-se bem a diferentes temperos e estilos culinários, desde os mais simples até os mais sofisticados. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} In Natura Hortaliças Fresco (Hortifruti) Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
