INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (392, 'Tomate Italiano', 'tomate italiano', 'Hortifrutigranjeiros', 1.0, '1 un', 'mercearia', '/images/produtos/1007601_f81b92b0bd31.jpg', 'Tomate Italiano, vendido em unidade ou por peso. Se destaca por sua forma alongada e polpa firme , características que o tornam um ingrediente versátil e de alta qualidade. Sua casca lisa e brilhante, de um vermelho vibrante, indica frescor e maturação ideal, prometendo um sabor adocicado e levemente ácido, com poucas sementes. A textura carnuda e a baixa quantidade de água são ideais para quem busca um tomate que mantenha sua estrutura em cozimentos prolongados, sem desmanchar facilmente. A versatilidade deste fruto é um de seus maiores trunfos na cozinha. Pode ser utilizado em molhos de longa fervura, como o molho de tomate caseiro, onde sua doçura natural se intensifica, resultando em um sabor profundo e autêntico. Em saladas, fatiado ou em cubos, adiciona cor e um toque fresco, complementando outros vegetais e temperos. Sua consistência também o torna uma excelente escolha para assados, onde carameliza levemente, liberando seus sucos e aromas. Para quem aprecia conservas, o tomate italiano é a base ideal para antepastos e conservas em azeite, preservando seu sabor e textura por mais tempo. A escolha deste tomate garante um toque de autenticidade e sabor em pratos que vão desde o dia a dia até ocasiões especiais, enriquecendo a experiência gastronômica com sua qualidade superior. É o item ideal para quem busca ingredientes frescos e um resultado delicioso em suas receitas, valorizando o sabor natural dos alimentos. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Hortaliças In Natura Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
