INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (394, 'Bergamota Caí / Montenegrina', 'bergamota caí / montenegrina', 'Hortifrutigranjeiros', 1.0, '1 un', 'mercearia', '/images/produtos/1001317_b36d8f98c2de.jpg', 'Bergamota Caí Montenegrina, vendida por unidade ou peso. Conhecida pelo sabor marcante e pela praticidade na hora de consumir, esta fruta cítrica conquista pelo perfume fresco, pela casca de coloração laranja intensa e pela polpa suculenta que se separa em gomos delicados e fáceis de comer. A variedade Montenegrina é bastante apreciada na região Sul do Brasil, especialmente por seu perfil de sabor. Ao descascar a fruta, o aroma cítrico se espalha e antecipa a experiência: os gomos apresentam textura macia, bastante suculência e um sabor que combina doçura com uma agradável acidez. Na hora do lanche, ela pode ser consumida in natura , basta descascar e separar os gomos. Por ser fácil de transportar e dispensar talheres ou preparos elaborados, é uma alternativa prática para levar ao trabalho, à escola, à faculdade ou para aproveitar durante um passeio. Na cozinha, a Bergamota Montenegrina vai muito além do consumo ao natural. Os gomos podem ser adicionados em saladas de frutas, iogurtes e bowls, trazendo um contraste cítrico e suculento. O suco é outra maneira de aproveitar a fruta, basta espremer os gomos e servir a bebida gelada ou combinar o suco com outras frutas, como laranja, abacaxi e morango. A bergamota também pode aparecer em preparações como geleias, caldas, mousses, tortas e bolos, nos quais seu aroma cítrico ajuda a criar um resultado mais perfumado e saboroso. A casca merece atenção especial, depois de bem higienizada, pode ser utilizada para aromatizar chás, preparar caldas ou acrescentar notas cítricas em massas de bolos e biscoitos. As raspas também podem finalizar sobremesas, trazendo perfume e um toque de cor ao prato. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Fresco (Hortifruti) Frutas In Natura Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
