INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (396, 'Maçã Fuji', 'maçã fuji', 'Hortifrutigranjeiros', 1.0, '1 un', 'mercearia', '/images/produtos/1001924_f498d7a43863.jpg', 'Maçã Fuji, vendida em unidade ou por peso. Reconhecida por sua aparência marcante, apresenta uma coloração que mescla tons de vermelho intenso com nuances amareladas, além de pequenas pintas claras, com a casca lisa e levemente brilhante. Ao primeiro contato, revela uma polpa crocante , extremamente suculenta. Seu sabor é predominantemente doce , com um leve toque ácido, que equilibra o paladar sem se tornar enjoativo. Essa harmonia faz com que a fruta seja amplamente apreciada por diferentes públicos, desde crianças até adultos que buscam uma alimentação mais equilibrada. Naturalmente rica em fibras alimentares , a maçã contribui para o bom funcionamento do sistema digestivo. A presença de vitamina C e compostos antioxidantes auxilia na proteção do organismo, fortalecendo o sistema imunológico. Na culinária, seu uso é bastante amplo e saboroso. Pode ser incorporada em preparações como torta de maçã com canela, crumble crocante com aveia, bolo caseiro ou até mesmo em compotas levemente adocicadas. Também combina muito bem em receitas salgadas, como saladas com folhas verdes, nozes e queijos ou acompanhando carnes assadas, trazendo um contraste equilibrado de sabores. Em cafés da manhã ou lanches, pode ser servida com iogurte, mel e granola. Além disso, é excelente para consumo puro, sendo uma opção prática para o dia a dia, especialmente para quem busca alternativas saudáveis entre as refeições. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid;