INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (398, 'Laranja Navelina', 'laranja navelina', 'Hortifrutigranjeiros', 1.0, '1 un', 'mercearia', '/images/produtos/1001408_62244636965a.jpg', 'Laranja Navelina, vendida por unidade ou por peso. É uma variedade amplamente apreciada por sua doçura e aroma cítrico marcante. Conhecida também como laranja de umbigo , essa fruta se destaca pela sua polpa suculenta e textura macia, características que a tornam uma das preferidas para o preparo de sucos naturais, garantindo uma bebida fresca e nutritiva. Além de ser consumida in natura , como uma opção saudável para sobremesas ou lanches intermediários, seus gomos podem ser incorporados em saladas verdes, proporcionando um contraste doce e refrescante. Pode, ainda, ser utilizada em combinações de saladas de frutas, em que seu sabor cítrico complementa outras frutas. A versatilidade dessa laranja vai além, podendo ser utilizada em receitas variadas, como molhos agridoces, cremes, geleias e pratos principais, onde seu suco e suas raspas adicionam um toque especial. Nutricionalmente, essa fruta é uma excelente fonte de vitaminas essenciais, como A, B e C, que fortalecem o sistema imunológico, melhoram a saúde da pele e contribuem para o bom funcionamento do organismo. Além disso, é rica em minerais importantes, como magnésio, fósforo e cálcio que auxiliam na saúde óssea e no equilíbrio eletrolítico. A fruta deve ser mantida em local seco e fresco, longe de fontes de calor e umidade. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-se