INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (400, 'Banana Prata Orgânica Naturale 800g', 'banana prata orgânica naturale 800g', 'Naturale', 1.0, '800g', 'mercearia', '/images/produtos/1098037_87e93dd13aa9.jpg', 'Banana Prata Orgânica, da marca Naturale, em embalagem com 800g. Cultivada sob rigorosos padrões orgânicos, esta fruta livre de agrotóxicos e fertilizantes sintéticos oferece uma experiência gustativa pura e autêntica. Sua textura macia e doçura equilibrada a tornam um lanche perfeito para qualquer hora do dia, sendo uma excelente fonte de energia natural para impulsionar as atividades cotidianas. A versatilidade deste alimento é um de seus grandes trunfos. Pode ser consumida in natura, adicionada a smoothies e vitaminas para um toque especial, ou incorporada em receitas de bolos, tortas e sobremesas, conferindo umidade e um sabor adocicado irresistível. Por ser orgânica , esta Banana Prata também é uma aliada valiosa para quem se preocupa com a saúde. Além disso, seu consumo pode ser feito em diferentes momentos do dia, seja no café da manhã, no lanche ou na sobremesa. Seu sabor e textura suaves a torna uma excelente opção para todas as idades. A embalagem prática preserva o frescor e as propriedades da fruta, garantindo que chegue até o consumidor em boas condições. O produto deve ser mantido em local seco e fresco, longe de fontes de calor e umidade. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Frutas Orgânicos Fresco (Hortifruti) In Natura Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
