INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (402, 'Conjunto com 3 Toalhas de Papel em Rolo Kitchen 19x19cm 120 folhas', 'conjunto com 3 toalhas de papel em rolo kitchen 19x19cm 120 folhas', 'Kitchen', 1.0, '1 un', 'higiene', '/images/produtos/1135421_b247879cdc10.jpg', 'Conjunto de Toalhas de Papel em Rolo, da marca Kitchen, em embalagem com 3 unidades de 120 folhas. Com folha dupla e medindo 19 x 19 centímetros, este conjunto de toalhas de papel em rolo foi desenvolvido para oferecer praticidade e eficiência em diversas tarefas do dia a dia. A embalagem contém três unidades, cada uma com 120 folhas, totalizando 360 folhas, o que assegura um suprimento duradouro para a casa ou estabelecimento. Sua composição de folha dupla confere uma robustez notável, permitindo que seja utilizado para lidar com líquidos derramados, limpeza de superfícies engorduradas ou até mesmo para secar as mãos com mais segurança e higiene. A tecnologia "Ultra Absorve" presente neste produto é um dos seus grandes diferenciais, pois maximiza a capacidade de absorção, tornando cada folha mais eficaz e reduzindo o desperdício. Isso significa que menos papel é necessário para realizar a mesma tarefa, gerando economia no longo prazo. Além de sua performance em absorção e resistência, o papel toalha da Kitchen é versátil e se adapta a múltiplos usos, seja na cozinha para secar louças, limpar bancadas, enxugar alimentos ou no escritório para pequenas emergências, sua confiabilidade é um fator-chave. A alta resistência evita que o papel se desfaça facilmente durante o uso, mesmo quando úmido, o que é essencial para uma limpeza eficiente. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Multiuso Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
