INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (403, 'Álcool Líquido 46% INPM Ecobac Zeppelin 1 Litro', 'álcool líquido 46% inpm ecobac zeppelin 1 litro', 'Zeppelin', 1.0, '1 l', 'mercearia', '/images/produtos/1114379_b7657308fabc.jpg', 'Álcool Líquido Ecobac 46º INPM, da marca Zeppelin, em garrafa com 1 litro. É um desinfetante bactericida de uso geral, que limpa e higieniza superfícies, utensílios e objetos de ambientes residenciais e comerciais, sendo indicado também para hospitais, laboratórios, clínicas e consultórios médicos por matar 99,9% das bactérias. Para evitar possíveis danos, não é recomendado para superfícies enceradas, laqueadas, pintadas e envernizadas. No ambiente residencial, é muito útil para a limpeza de banheiros, de cozinhas e de áreas com animais domésticos. Por recomendação do fabricante, não deve ser utilizado para desinfecção de alimentos ou derramado sobre o fogo. Para sua conservação, é recomendado que seja mantido em local seco e fresco, longe da incidência de luz solar direta. Deve ser guardado fora do alcance de crianças e de animais domésticos.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
