INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (405, 'Detergente Líquido Limpol Cristal 500ml', 'detergente líquido limpol cristal 500ml', 'Limpol', 1.0, '500ml', 'higiene', '/images/produtos/1013839_4423685b5645.jpg', 'Detergente Líquido Cristal Limpol, da marca Bombril, em embalagem com 500 mililitros. É a solução perfeita para quem busca eficiência na limpeza. Sua fórmula inovadora conta com glicerina, que proporciona um cuidado extra para as mãos, evitando o ressecamento mesmo após o uso prolongado. Pensado para facilitar a rotina, este detergente apresenta uma fórmula transparente e textura leve que espalha com facilidade, formando uma espuma consistente que envolve a sujeira e ajuda a remover resíduos com rapidez, deixando utensílios com um aspecto limpo e bem cuidado. Ao entrar em contato com a água, sua ação se intensifica, auxiliando na remoção de gordura de panelas, pratos, copos e talheres. Seu enxágue é simples e rápido, contribuindo para uma experiência mais ágil no dia a dia. Sua composição concentrada permite um ótimo rendimento , já que pequenas quantidades são suficientes para resultados completos. Outro diferencial é sua aplicação versátil, podendo ser utilizado também na limpeza de superfícies como pias, bancadas e até na remoção de pequenas manchas em tecidos, sempre com cuidado e atenção ao material. A embalagem prática facilita o manuseio e contribui para o controle da quantidade utilizada, evitando excessos e desperdícios. A transparência do produto reforça a ideia de pureza e simplicidade, combinando com quem busca soluções eficientes sem complicações. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Multiuso Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
