INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (406, 'Toalhas de Papel em Rolo Claramax Premium 20x19cm 120 folhas', 'toalhas de papel em rolo claramax premium 20x19cm 120 folhas', 'Claramax', 1.0, '1 un', 'higiene', '/images/produtos/1005918_45239260def1.jpg', 'Toalhas de Papel Premium, da marca ClaraMax, em rolo contendo 120 folhas. Oferece máxima absorção e resistência, sendo a escolha ideal para quem busca praticidade e eficiência nas tarefas diárias. O rolo é perfeito para diversas atividades, desde a secagem de mãos e utensílios até a limpeza de superfícies e absorção de líquidos em cozinhas e outros ambientes. Pode ser usado para a secagem de mãos em banheiros e cozinhas, limpeza de superfícies, como bancadas e mesas, absorção de líquidos e gorduras durante o preparo de alimentos ou até mesmo como um substituto prático para toalhas de tecido em pequenas limpezas rápidas do dia a dia. Ideal para quem busca um papel toalha versátil e de alta qualidade para diversas situações cotidianas.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
