INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (408, 'Guardanapos de Papel 30x30cm Linea Utilo 50 Unidades', 'guardanapos de papel 30x30cm linea utilo 50 unidades', 'Linea Utilo', 1.0, '50 un', 'higiene', '/images/produtos/1097139_08ece0db1da1.jpg', 'Guardanapo de Papel, da marca Linea Utilo, em embalagem com 50 unidades de 30x30cm. Estes guardanapos são práticos e versáteis, ideais para usar em diversas ocasiões. Com suas dimensões, cada unidade oferece uma área de cobertura generosa , ideal para acompanhar refeições, lanches ou para auxiliar em momentos de limpeza. A composição deste guardanapo prioriza a absorção e a resistência , características essenciais para um uso confiável. Sua textura suave proporciona um toque agradável , enquanto a capacidade de absorção garante que líquidos sejam contidos de forma eficaz. A quantidade é pensada para atender tanto ao uso doméstico quanto ao de pequenos estabelecimentos, oferecendo um bom custo-benefício. Este guardanapo é um aliado funcional na cozinha, seja na sala de jantar ou até mesmo em eventos sociais. Com sua utilização, é possível manter a higiene e a organização durante as refeições, seja em um almoço casual em família ou em uma celebração mais elaborada. Pode ser utilizado para diversas outras finalidades, como na limpeza rápida de superfícies, na secagem das mãos ou até mesmo como base para pequenos petiscos. Além disso, é uma escolha conveniente para ser levado em viagens, piqueniques e passeios, pois oferece uma solução higiênica e descartável , permitindo o descarte adequado do lixo. .index-selos { display:flex; }.grupo { display:flex; }.selo { text-align:center; border:1px solid transparent; padding:15px 0; width:100%; }.selo img { width:100px; }.selo p { font-weight:bold; font-size:12px; text-transform:uppercase; width:140px;margin:0;line-height:16px;}@media screen and (max-width:1023px) {.grupo { display:grid; grid-template-columns:1fr 1fr; justify-items:center; max-width:300px; }.selo { width:100%; }.index-selos { display:block; justify-self:center; }} Multiuso Descrição gerada por Inteligência Artificial. Confira os detalhes antes da compra.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
