INSERT INTO produto (id, nome, nome_normalizado, marca, quantidade, unidade, categoria, imagem_url, descricao) VALUES (409, 'Detergente Líquido Cristal Splendo 500ml', 'detergente líquido cristal splendo 500ml', 'Splendo', 1.0, '500ml', 'higiene', '/images/produtos/1096043_99c992e8c06c.jpg', 'Livre de fragrância, o Lava-louças Líquido Cristal da marca Splendo vem em embalagem com 500 mililitros. O produto, que também é conhecido como detergente, é formulado com ativos que ajudam na remoção de variados tipos de sujeiras e gorduras em geral. Ideal para higienização de diversos objetos e superfícies, desde louças até pias e bancadas, é dermatologicamente testado. Desenvolvido com uma fórmula avançada, este detergente proporciona uma limpeza profunda e eficaz, removendo até as sujeiras mais difíceis e deixando os utensílios domésticos com um brilho impecável. Para obter os melhores resultados, aplique uma pequena quantidade do detergente diretamente na esponja ou dilua em água, esfregue a superfície desejada e enxágue bem. Antes de utilizar o produto, é recomendado que seja feita a leitura das instruções no rótulo. Manter fora do alcance de crianças e animais domésticos.') ON CONFLICT (id) DO UPDATE SET imagem_url = EXCLUDED.imagem_url, descricao = EXCLUDED.descricao;
